window.ETEXTBOOK={"units": [{"id": "u1", "title": "第四部分导读", "sections": [{"id": "u1_s0", "title": "第四部分导读", "paras": [{"id": "u1_s0_p1", "buf": ["China, with its profound historical legacy spanning thousands of years, has evolved into a vibrant modern society rich in vitality and opportunity. Its ancient economic wisdom laid a foundation for sustained growth and prosperity. Today, the nation's remarkable achievements reflect a spirit of innovation and shared aspirations. At the same time, contemporary life in China is marked by cultural richness and a sense of well-being—people now enjoy more leisure time, take part in diverse cultural activities, and explore the country's breathtaking natural landscapes and cultural heritage sites."], "text": "China, with its profound historical legacy spanning thousands of years, has evolved into a vibrant modern society rich in vitality and opportunity. Its ancient economic wisdom laid a foundation for sustained growth and prosperity. Today, the nation's remarkable achievements reflect a spirit of innovation and shared aspirations. At the same time, contemporary life in China is marked by cultural richness and a sense of well-being—people now enjoy more leisure time, take part in diverse cultural activities, and explore the country's breathtaking natural landscapes and cultural heritage sites.", "chunks": ["China, with its profound historical legacy spanning thousands of years, has evolved into a vibrant modern society rich in vitality and opportunity. Its ancient economic wisdom laid a foundation for sustained growth and prosperity. Today, the nation's remarkable achievements reflect a spirit of innovation and shared aspirations. At the same time, contemporary life in China is marked by cultural richness and a sense of well-being—people now enjoy more leisure time, take part in diverse cultural activities, and explore the country's breathtaking natural landscapes and cultural heritage sites."]}]}]}, {"id": "u2", "title": "导入问题", "sections": [{"id": "u2_s0", "title": "导入问题", "paras": [{"id": "u2_s0_p1", "buf": ["1 Which ancient Chinese philosophy do you know that influenced China's economy in the past?"], "text": "1 Which ancient Chinese philosophy do you know that influenced China's economy in the past?", "chunks": ["1 Which ancient Chinese philosophy do you know that influenced China's economy in the past?"]}, {"id": "u2_s0_p2", "buf": ["2 When did China begin its reform and opening-up policy?"], "text": "2 When did China begin its reform and opening-up policy?", "chunks": ["2 When did China begin its reform and opening-up policy?"]}, {"id": "u2_s0_p3", "buf": ["3 Which mobile payment app do you use most often, and when do you usually use it?"], "text": "3 Which mobile payment app do you use most often, and when do you usually use it?", "chunks": ["3 Which mobile payment app do you use most often, and when do you usually use it?"]}]}]}, {"id": "u3", "title": "中国传统经济思想与商业", "sections": [{"id": "u3_s1", "title": "中国传统经济思想", "paras": [{"id": "u3_s1_p1", "buf": ["Traditional Chinese economic thought has always been deeply intertwined with the country's philosophical traditions. Confucianism, Daoism, and Legalism complemented one another and together shaped economic practices and social behaviour. These philosophies provided distinct frameworks for commercial activity, and influenced the course of China's economic history."], "text": "Traditional Chinese economic thought has always been deeply intertwined with the country's philosophical traditions. Confucianism, Daoism, and Legalism complemented one another and together shaped economic practices and social behaviour. These philosophies provided distinct frameworks for commercial activity, and influenced the course of China's economic history.", "chunks": ["Traditional Chinese economic thought has always been deeply intertwined with the country's philosophical traditions. Confucianism, Daoism, and Legalism complemented one another and together shaped economic practices and social behaviour. These philosophies provided distinct frameworks for commercial activity, and influenced the course of China's economic history."]}]}, {"id": "u3_s2", "title": "儒家：经济伦理与社会责任", "paras": [{"id": "u3_s2_p1", "buf": ["Confucianism places great emphasis on moral values, social harmony, and ethical behaviour, and has had an enduring influence on the economic practices in China. Confucian thought advocates a balanced approach to righteousness and profit, emphasising that moral integrity and material benefit should be pursued in harmony."], "text": "Confucianism places great emphasis on moral values, social harmony, and ethical behaviour, and has had an enduring influence on the economic practices in China. Confucian thought advocates a balanced approach to righteousness and profit, emphasising that moral integrity and material benefit should be pursued in harmony.", "chunks": ["Confucianism places great emphasis on moral values, social harmony, and ethical behaviour, and has had an enduring influence on the economic practices in China. Confucian thought advocates a balanced approach to righteousness and profit, emphasising that moral integrity and material benefit should be pursued in harmony."]}, {"id": "u3_s2_p2", "buf": ["The piaohao (票号), or draft banks, of the Qing Dynasty, are a prime example of this concept. Established by merchants from Shanxi, these institutions were based on mutual trust and responsibility, aligning with Confucian ideals of integrity and social welfare. Merchants involved in the piaohao not only achieved financial success but also supported their communities, showing how economic activity could foster social harmony."], "text": "The piaohao (票号), or draft banks, of the Qing Dynasty, are a prime example of this concept. Established by merchants from Shanxi, these institutions were based on mutual trust and responsibility, aligning with Confucian ideals of integrity and social welfare. Merchants involved in the piaohao not only achieved financial success but also supported their communities, showing how economic activity could foster social harmony.", "chunks": ["The piaohao (票号), or draft banks, of the Qing Dynasty, are a prime example of this concept. Established by merchants from Shanxi, these institutions were based on mutual trust and responsibility, aligning with Confucian ideals of integrity and social welfare. Merchants involved in the piaohao not only achieved financial success but also supported their communities, showing how economic activity could foster social harmony."]}, {"id": "u3_s2_p3", "buf": ["In traditional family-run businesses, long-term stability and moral leadership were regarded as essential. Success was seen not merely as personal achievement but as a responsibility to both the family and society. Confucian values such as filial piety and ethical conduct, together with a strong emphasis on education, were considered vital for sustaining prosperity and ensuring business success in a socially responsible manner."], "text": "In traditional family-run businesses, long-term stability and moral leadership were regarded as essential. Success was seen not merely as personal achievement but as a responsibility to both the family and society. Confucian values such as filial piety and ethical conduct, together with a strong emphasis on education, were considered vital for sustaining prosperity and ensuring business success in a socially responsible manner.", "chunks": ["In traditional family-run businesses, long-term stability and moral leadership were regarded as essential. Success was seen not merely as personal achievement but as a responsibility to both the family and society. Confucian values such as filial piety and ethical conduct, together with a strong emphasis on education, were considered vital for sustaining prosperity and ensuring business success in a socially responsible manner."]}]}, {"id": "u3_s3", "title": "道家：无为与天人和谐", "paras": [{"id": "u3_s3_p1", "buf": ["In the economic sphere, the Daoist principle of non-action is often interpreted as acting in accordance with market principles and refraining from arbitrary or reckless intervention. In agricultural practice, Daoism advocates respecting the vitality and creativity of nature and living in harmony with it. Farmers work in tune with nature's cycles to ensure sustainable yields while avoiding the overexploitation of resources."], "text": "In the economic sphere, the Daoist principle of non-action is often interpreted as acting in accordance with market principles and refraining from arbitrary or reckless intervention. In agricultural practice, Daoism advocates respecting the vitality and creativity of nature and living in harmony with it. Farmers work in tune with nature's cycles to ensure sustainable yields while avoiding the overexploitation of resources.", "chunks": ["In the economic sphere, the Daoist principle of non-action is often interpreted as acting in accordance with market principles and refraining from arbitrary or reckless intervention. In agricultural practice, Daoism advocates respecting the vitality and creativity of nature and living in harmony with it. Farmers work in tune with nature's cycles to ensure sustainable yields while avoiding the overexploitation of resources."]}, {"id": "u3_s3_p2", "buf": ["Daoist ideas have also influenced urban planning. For example, the central area of Xi'an during the Tang Dynasty was designed based on the principles of balance and harmony. The layout aimed to harmonise human activity with nature, reflecting the Daoist belief that economic prosperity and urban development should respect and remain in balance with the natural environment."], "text": "Daoist ideas have also influenced urban planning. For example, the central area of Xi'an during the Tang Dynasty was designed based on the principles of balance and harmony. The layout aimed to harmonise human activity with nature, reflecting the Daoist belief that economic prosperity and urban development should respect and remain in balance with the natural environment.", "chunks": ["Daoist ideas have also influenced urban planning. For example, the central area of Xi'an during the Tang Dynasty was designed based on the principles of balance and harmony. The layout aimed to harmonise human activity with nature, reflecting the Daoist belief that economic prosperity and urban development should respect and remain in balance with the natural environment."]}]}, {"id": "u3_s4", "title": "法家：严法与行政统一", "paras": [{"id": "u3_s4_p1", "buf": ["Legalism prioritises strong state control and regulation to maintain order and strengthen the state. Legalists believed that human nature was inherently self-interested and needed to be regulated through strict laws and effective governance."], "text": "Legalism prioritises strong state control and regulation to maintain order and strengthen the state. Legalists believed that human nature was inherently self-interested and needed to be regulated through strict laws and effective governance.", "chunks": ["Legalism prioritises strong state control and regulation to maintain order and strengthen the state. Legalists believed that human nature was inherently self-interested and needed to be regulated through strict laws and effective governance."]}, {"id": "u3_s4_p2", "buf": ["The Qin Dynasty, under the rule of Emperor Qin Shihuang, is the most prominent example of Legalist governance in practice. Centralised authority and legal reforms, such as the standardisation of currency, weights, and measures, helped unify the empire and facilitated trade across vast distances, promoting economic integration. Infrastructure projects, such as the construction of roads, canals, and the Great Wall, also reflected Legalist ideals. These initiatives were designed not only to support commerce but also to solidify state control, secure resources, and maintain order across the empire. This focus on administrative uniformity and centralised state power laid the groundwork for economic growth and the unification of the six states."], "text": "The Qin Dynasty, under the rule of Emperor Qin Shihuang, is the most prominent example of Legalist governance in practice. Centralised authority and legal reforms, such as the standardisation of currency, weights, and measures, helped unify the empire and facilitated trade across vast distances, promoting economic integration. Infrastructure projects, such as the construction of roads, canals, and the Great Wall, also reflected Legalist ideals. These initiatives were designed not only to support commerce but also to solidify state control, secure resources, and maintain order across the empire. This focus on administrative uniformity and centralised state power laid the groundwork for economic growth and the unification of the six states.", "chunks": ["The Qin Dynasty, under the rule of Emperor Qin Shihuang, is the most prominent example of Legalist governance in practice. Centralised authority and legal reforms, such as the standardisation of currency, weights, and measures, helped unify the empire and facilitated trade across vast distances, promoting economic integration. Infrastructure projects, such as the construction of roads, canals, and the Great Wall, also reflected Legalist ideals. These initiatives were designed not only to support commerce but also to solidify state control, secure resources, and maintain order across the empire. This focus on administrative uniformity and centralised state power laid the groundwork for economic growth and the unification of the six states."]}]}, {"id": "u3_s5", "title": "历史商业发展", "paras": [{"id": "u3_s5_p1", "buf": ["The intersection of economic philosophy and historical commercial activity is most evident in China's trade networks, particularly along the Silk Road. Established during the Han Dynasty, the ancient Silk Road was a vast network of trade routes that connected China to regions across Asia, Europe, and Africa. During the Han and Tang dynasties, China experienced an unprecedented level of social and economic prosperity. This remarkable flourishing made China a leading force in the development of the Silk Road, which reflects the Confucian ideal of social responsibility. Successive Chinese governments also played an indispensable role in the development of the Silk Road. By establishing official posts, formulating laws and policies, and strengthening institutional governance, they provided the regulatory foundation for trade—a practical embodiment of Legalist principles of strong law and governance."], "text": "The intersection of economic philosophy and historical commercial activity is most evident in China's trade networks, particularly along the Silk Road. Established during the Han Dynasty, the ancient Silk Road was a vast network of trade routes that connected China to regions across Asia, Europe, and Africa. During the Han and Tang dynasties, China experienced an unprecedented level of social and economic prosperity. This remarkable flourishing made China a leading force in the development of the Silk Road, which reflects the Confucian ideal of social responsibility. Successive Chinese governments also played an indispensable role in the development of the Silk Road. By establishing official posts, formulating laws and policies, and strengthening institutional governance, they provided the regulatory foundation for trade—a practical embodiment of Legalist principles of strong law and governance.", "chunks": ["The intersection of economic philosophy and historical commercial activity is most evident in China's trade networks, particularly along the Silk Road. Established during the Han Dynasty, the ancient Silk Road was a vast network of trade routes that connected China to regions across Asia, Europe, and Africa. During the Han and Tang dynasties, China experienced an unprecedented level of social and economic prosperity. This remarkable flourishing made China a leading force in the development of the Silk Road, which reflects the Confucian ideal of social responsibility. Successive Chinese governments also played an indispensable role in the development of the Silk Road. By establishing official posts, formulating laws and policies, and strengthening institutional governance, they provided the regulatory foundation for trade—a practical embodiment of Legalist principles of strong law and governance."]}, {"id": "u3_s5_p2", "buf": ["Another example can be seen in agricultural development during the Tang Dynasty, when the rulers recognised the vital importance of agriculture to the nation and its people. In the Hexi Corridor, they transformed long stretches of desert into fertile farmland by making use of its natural conditions. Irrigation from the snowmelt of the Qilian Mountains enabled sustainable cultivation, allowing the land to evolve from a mere passage and strategic stronghold into a productive agricultural and economic zone. This transformation illustrates Daoist principles of harmony between humanity and nature."], "text": "Another example can be seen in agricultural development during the Tang Dynasty, when the rulers recognised the vital importance of agriculture to the nation and its people. In the Hexi Corridor, they transformed long stretches of desert into fertile farmland by making use of its natural conditions. Irrigation from the snowmelt of the Qilian Mountains enabled sustainable cultivation, allowing the land to evolve from a mere passage and strategic stronghold into a productive agricultural and economic zone. This transformation illustrates Daoist principles of harmony between humanity and nature.", "chunks": ["Another example can be seen in agricultural development during the Tang Dynasty, when the rulers recognised the vital importance of agriculture to the nation and its people. In the Hexi Corridor, they transformed long stretches of desert into fertile farmland by making use of its natural conditions. Irrigation from the snowmelt of the Qilian Mountains enabled sustainable cultivation, allowing the land to evolve from a mere passage and strategic stronghold into a productive agricultural and economic zone. This transformation illustrates Daoist principles of harmony between humanity and nature."]}, {"id": "u3_s5_p3", "buf": ["Traditional Chinese economic thought has played a key role in the evolution of China's economy. Philosophies from various schools influenced not only the practices of individual merchants but also the overall organisation of the economy. They contributed to the growth of trade networks, the establishment of ethical business practices, and the creation of an integrated and stable economic system."], "text": "Traditional Chinese economic thought has played a key role in the evolution of China's economy. Philosophies from various schools influenced not only the practices of individual merchants but also the overall organisation of the economy. They contributed to the growth of trade networks, the establishment of ethical business practices, and the creation of an integrated and stable economic system.", "chunks": ["Traditional Chinese economic thought has played a key role in the evolution of China's economy. Philosophies from various schools influenced not only the practices of individual merchants but also the overall organisation of the economy. They contributed to the growth of trade networks, the establishment of ethical business practices, and the creation of an integrated and stable economic system."]}]}]}, {"id": "u4", "title": "当代中国经济发展", "sections": [{"id": "u4_s0", "title": "当代中国经济发展", "paras": [{"id": "u4_s0_p1", "buf": ["Building on the philosophical foundations laid by Confucianism, Daoism, and Legalism, China's contemporary economic framework continues to embody values of harmony, pragmatism, and effective governance. These enduring principles have guided policy design, institutional reform, and the pursuit of socially balanced development. In this way, traditional wisdom forms a cultural link between ancient economic thought and modern economic transformation. Since the founding of the People's Republic of China, the nation's economy has undergone a profound transformation, continuously advancing towards modernisation."], "text": "Building on the philosophical foundations laid by Confucianism, Daoism, and Legalism, China's contemporary economic framework continues to embody values of harmony, pragmatism, and effective governance. These enduring principles have guided policy design, institutional reform, and the pursuit of socially balanced development. In this way, traditional wisdom forms a cultural link between ancient economic thought and modern economic transformation. Since the founding of the People's Republic of China, the nation's economy has undergone a profound transformation, continuously advancing towards modernisation.", "chunks": ["Building on the philosophical foundations laid by Confucianism, Daoism, and Legalism, China's contemporary economic framework continues to embody values of harmony, pragmatism, and effective governance. These enduring principles have guided policy design, institutional reform, and the pursuit of socially balanced development. In this way, traditional wisdom forms a cultural link between ancient economic thought and modern economic transformation. Since the founding of the People's Republic of China, the nation's economy has undergone a profound transformation, continuously advancing towards modernisation."]}]}, {"id": "u4_s1", "title": "改革开放", "paras": [{"id": "u4_s1_p1", "buf": ["the Third Plenary Session of the 11th CPC Central Committee: Held in Beijing in December 1978, this key meeting marked the start of China's economic reforms. Led by Deng Xiaoping, it set the focus of the Party and the country's work on economic development, initiating the transition from a planned economy to a market-oriented one and laying the groundwork for China's modernisation and its reform and opening up. 中国共产党第十一届中央委员会第三次全体会议，于1978年12月在北京举行。这次关键会议标志着中国经济改革的开始。在邓小平的领导下，会议将党和国家的工作重点放在经济建设上，开启了从计划经济向市场经济的转型，为中国的现代化进程和改革开放奠定了基础。"], "text": "the Third Plenary Session of the 11th CPC Central Committee: Held in Beijing in December 1978, this key meeting marked the start of China's economic reforms. Led by Deng Xiaoping, it set the focus of the Party and the country's work on economic development, initiating the transition from a planned economy to a market-oriented one and laying the groundwork for China's modernisation and its reform and opening up. 中国共产党第十一届中央委员会第三次全体会议，于1978年12月在北京举行。这次关键会议标志着中国经济改革的开始。在邓小平的领导下，会议将党和国家的工作重点放在经济建设上，开启了从计划经济向市场经济的转型，为中国的现代化进程和改革开放奠定了基础。", "chunks": ["the Third Plenary Session of the 11th CPC Central Committee: Held in Beijing in December 1978, this key meeting marked the start of China's economic reforms. Led by Deng Xiaoping, it set the focus of the Party and the country's work on economic development, initiating the transition from a planned economy to a market-oriented one and laying the groundwork for China's modernisation and its reform and opening up. 中国共产党第十一届中央委员会第三次全体会议，于1978年12月在北京举行。这次关键会议标志着中国经济改革的开始。在邓小平的领导下，会议将党和国家的工作重点放在经济建设上，开启了从计划经济向市场经济的转型，为中国的现代化进程和改革开放奠定了基础。"]}, {"id": "u4_s1_p2", "buf": ["In 1978, the Third Plenary Session of the 11th CPC Central Committee marked a pivotal moment in China's history, as the country began to embrace reform and opening up. Reform seeks to fundamentally reshape the economic structure that once constrained the development of productive forces, establishing and improving a socialist market economy while advancing related changes in the political system and other institutional areas to ensure overall coordination. Opening up, meanwhile, focuses on external engagement—actively participating in international cooperation and competition under the conditions of economic globalisation, broadening exchanges with other countries, and drawing on the outstanding achievements of human civilisation to promote China's development and modernisation."], "text": "In 1978, the Third Plenary Session of the 11th CPC Central Committee marked a pivotal moment in China's history, as the country began to embrace reform and opening up. Reform seeks to fundamentally reshape the economic structure that once constrained the development of productive forces, establishing and improving a socialist market economy while advancing related changes in the political system and other institutional areas to ensure overall coordination. Opening up, meanwhile, focuses on external engagement—actively participating in international cooperation and competition under the conditions of economic globalisation, broadening exchanges with other countries, and drawing on the outstanding achievements of human civilisation to promote China's development and modernisation.", "chunks": ["In 1978, the Third Plenary Session of the 11th CPC Central Committee marked a pivotal moment in China's history, as the country began to embrace reform and opening up. Reform seeks to fundamentally reshape the economic structure that once constrained the development of productive forces, establishing and improving a socialist market economy while advancing related changes in the political system and other institutional areas to ensure overall coordination. Opening up, meanwhile, focuses on external engagement—actively participating in international cooperation and competition under the conditions of economic globalisation, broadening exchanges with other countries, and drawing on the outstanding achievements of human civilisation to promote China's development and modernisation."]}]}, {"id": "u4_s2", "title": "起步与目标探索阶段", "paras": [{"id": "u4_s2_p1", "buf": ["In 1978, China initiated its historic reform and opening-up policy, which represented a strategic pivot towards unleashing productive forces and prioritising economic development. This transformation reflected China's pursuit of progress while maintaining social stability. The establishment of Special Economic Zones in cities like Shenzhen and Zhuhai embodied a pragmatic approach to foreign economic engagement, with flexibility and experimentation at the core. These zones attracted foreign investment through tax incentives and enabled China to absorb advanced technologies from abroad while remaining rooted in its traditional values."], "text": "In 1978, China initiated its historic reform and opening-up policy, which represented a strategic pivot towards unleashing productive forces and prioritising economic development. This transformation reflected China's pursuit of progress while maintaining social stability. The establishment of Special Economic Zones in cities like Shenzhen and Zhuhai embodied a pragmatic approach to foreign economic engagement, with flexibility and experimentation at the core. These zones attracted foreign investment through tax incentives and enabled China to absorb advanced technologies from abroad while remaining rooted in its traditional values.", "chunks": ["In 1978, China initiated its historic reform and opening-up policy, which represented a strategic pivot towards unleashing productive forces and prioritising economic development. This transformation reflected China's pursuit of progress while maintaining social stability. The establishment of Special Economic Zones in cities like Shenzhen and Zhuhai embodied a pragmatic approach to foreign economic engagement, with flexibility and experimentation at the core. These zones attracted foreign investment through tax incentives and enabled China to absorb advanced technologies from abroad while remaining rooted in its traditional values."]}, {"id": "u4_s2_p2", "buf": ["During the early period of reform and opening up, China placed strong emphasis on the import of technology as a means of accelerating industrial development. By drawing on foreign expertise, China was able to modernise its industries rapidly and participate more effectively in the global division of labour. This strategy reflected the Chinese concept of \"learning from others\", which involves acquiring knowledge while preserving cultural distinctiveness. This not only enhanced China's manufacturing capabilities but also laid the foundation for the country's deeper integration into the global marketplace and its participation in international competition."], "text": "During the early period of reform and opening up, China placed strong emphasis on the import of technology as a means of accelerating industrial development. By drawing on foreign expertise, China was able to modernise its industries rapidly and participate more effectively in the global division of labour. This strategy reflected the Chinese concept of \"learning from others\", which involves acquiring knowledge while preserving cultural distinctiveness. This not only enhanced China's manufacturing capabilities but also laid the foundation for the country's deeper integration into the global marketplace and its participation in international competition.", "chunks": ["During the early period of reform and opening up, China placed strong emphasis on the import of technology as a means of accelerating industrial development. By drawing on foreign expertise, China was able to modernise its industries rapidly and participate more effectively in the global division of labour. This strategy reflected the Chinese concept of \"learning from others\", which involves acquiring knowledge while preserving cultural distinctiveness. This not only enhanced China's manufacturing capabilities but also laid the foundation for the country's deeper integration into the global marketplace and its participation in international competition."]}]}, {"id": "u4_s3", "title": "社会主义市场经济体制框架初步建立阶段", "paras": [{"id": "u4_s3_p1", "buf": ["This period was marked by the establishment of a socialist market economy, following the 14th National Congress of the Communist Party of China in 1992. The government decided to accelerate the pace of reform and opening up, aiming to balance efficiency and fairness in the allocation of resources. This shift not only strengthened the economy but also raised the standard of living for the Chinese people. As a result, citizens experienced a growing sense of hope and ambition as expanding economic opportunities opened new paths towards personal and national prosperity. This transformation drew upon the enduring Chinese cultural value of self-improvement, fostering both collective and individual progress."], "text": "This period was marked by the establishment of a socialist market economy, following the 14th National Congress of the Communist Party of China in 1992. The government decided to accelerate the pace of reform and opening up, aiming to balance efficiency and fairness in the allocation of resources. This shift not only strengthened the economy but also raised the standard of living for the Chinese people. As a result, citizens experienced a growing sense of hope and ambition as expanding economic opportunities opened new paths towards personal and national prosperity. This transformation drew upon the enduring Chinese cultural value of self-improvement, fostering both collective and individual progress.", "chunks": ["This period was marked by the establishment of a socialist market economy, following the 14th National Congress of the Communist Party of China in 1992. The government decided to accelerate the pace of reform and opening up, aiming to balance efficiency and fairness in the allocation of resources. This shift not only strengthened the economy but also raised the standard of living for the Chinese people. As a result, citizens experienced a growing sense of hope and ambition as expanding economic opportunities opened new paths towards personal and national prosperity. This transformation drew upon the enduring Chinese cultural value of self-improvement, fostering both collective and individual progress."]}, {"id": "u4_s3_p2", "buf": ["A significant focus during this transformative era was the reform of state-owned enterprises, which had long been the backbone of China's economy. The goal was to modernise these enterprises and enhance their competitiveness and operational efficiency in the global marketplace. The modern enterprise system introduced during this period gave firms greater managerial autonomy, clarified property rights, and promoted corporate governance, laying the groundwork for more accountability and efficiency. By reforming management practices and encouraging private investment, China sought to create a dynamic industrial sector capable of thriving in an increasingly globalised world."], "text": "A significant focus during this transformative era was the reform of state-owned enterprises, which had long been the backbone of China's economy. The goal was to modernise these enterprises and enhance their competitiveness and operational efficiency in the global marketplace. The modern enterprise system introduced during this period gave firms greater managerial autonomy, clarified property rights, and promoted corporate governance, laying the groundwork for more accountability and efficiency. By reforming management practices and encouraging private investment, China sought to create a dynamic industrial sector capable of thriving in an increasingly globalised world.", "chunks": ["A significant focus during this transformative era was the reform of state-owned enterprises, which had long been the backbone of China's economy. The goal was to modernise these enterprises and enhance their competitiveness and operational efficiency in the global marketplace. The modern enterprise system introduced during this period gave firms greater managerial autonomy, clarified property rights, and promoted corporate governance, laying the groundwork for more accountability and efficiency. By reforming management practices and encouraging private investment, China sought to create a dynamic industrial sector capable of thriving in an increasingly globalised world."]}]}, {"id": "u4_s4", "title": "进一步完善社会主义市场经济体制阶段", "paras": [{"id": "u4_s4_p1", "buf": ["China's accession (正式加入) to the World Trade Organization (WTO) marked a transformative moment in the nation's economic development. It enabled China to enhance its international standing and adhere to global trade norms. This milestone brought profound transformation to both China and the global economy. China's remarkable growth has been widely recognised, and its continuously expanding market openness has generated win-win outcomes for China and the world economy. Following China's entry into the WTO, the country's integration into the global economy deepened, stimulating new waves of foreign investment. China's opening up has evolved from a policy-based stage to an institutional one. Previously guided mainly by pilot initiatives and administrative directives, it has become a predictable, rule-based system of openness grounded in a comprehensive legal framework. During this stage, China experienced rapid industrialisation and urbanisation that reshaped its economic and social landscape."], "text": "China's accession (正式加入) to the World Trade Organization (WTO) marked a transformative moment in the nation's economic development. It enabled China to enhance its international standing and adhere to global trade norms. This milestone brought profound transformation to both China and the global economy. China's remarkable growth has been widely recognised, and its continuously expanding market openness has generated win-win outcomes for China and the world economy. Following China's entry into the WTO, the country's integration into the global economy deepened, stimulating new waves of foreign investment. China's opening up has evolved from a policy-based stage to an institutional one. Previously guided mainly by pilot initiatives and administrative directives, it has become a predictable, rule-based system of openness grounded in a comprehensive legal framework. During this stage, China experienced rapid industrialisation and urbanisation that reshaped its economic and social landscape.", "chunks": ["China's accession (正式加入) to the World Trade Organization (WTO) marked a transformative moment in the nation's economic development. It enabled China to enhance its international standing and adhere to global trade norms. This milestone brought profound transformation to both China and the global economy. China's remarkable growth has been widely recognised, and its continuously expanding market openness has generated win-win outcomes for China and the world economy. Following China's entry into the WTO, the country's integration into the global economy deepened, stimulating new waves of foreign investment. China's opening up has evolved from a policy-based stage to an institutional one. Previously guided mainly by pilot initiatives and administrative directives, it has become a predictable, rule-based system of openness grounded in a comprehensive legal framework. During this stage, China experienced rapid industrialisation and urbanisation that reshaped its economic and social landscape."]}, {"id": "u4_s4_p2", "buf": ["the Belt and Road Initiative: In 2013, President Xi Jinping raised the initiatives of joining with others to build a Silk Road Economic Belt and a 21st Century Maritime Silk Road, known collectively as the Belt and Road Initiative (BRI). The BRI takes on the Silk Road spirit characterised by peace and cooperation, openness and inclusiveness, mutual learning, and mutual benefit. \"一带一路\"倡议。2013年，习近平主席提出共同建设\"丝绸之路经济带\"和\"21世纪海上丝绸之路\"的重大倡议，即共建\"一带一路\"倡议。\"一带一路\"倡议秉持和平合作、开放包容、互学互鉴、互利共赢的丝绸之路精神。"], "text": "the Belt and Road Initiative: In 2013, President Xi Jinping raised the initiatives of joining with others to build a Silk Road Economic Belt and a 21st Century Maritime Silk Road, known collectively as the Belt and Road Initiative (BRI). The BRI takes on the Silk Road spirit characterised by peace and cooperation, openness and inclusiveness, mutual learning, and mutual benefit. \"一带一路\"倡议。2013年，习近平主席提出共同建设\"丝绸之路经济带\"和\"21世纪海上丝绸之路\"的重大倡议，即共建\"一带一路\"倡议。\"一带一路\"倡议秉持和平合作、开放包容、互学互鉴、互利共赢的丝绸之路精神。", "chunks": ["the Belt and Road Initiative: In 2013, President Xi Jinping raised the initiatives of joining with others to build a Silk Road Economic Belt and a 21st Century Maritime Silk Road, known collectively as the Belt and Road Initiative (BRI). The BRI takes on the Silk Road spirit characterised by peace and cooperation, openness and inclusiveness, mutual learning, and mutual benefit. \"一带一路\"倡议。2013年，习近平主席提出共同建设\"丝绸之路经济带\"和\"21世纪海上丝绸之路\"的重大倡议，即共建\"一带一路\"倡议。\"一带一路\"倡议秉持和平合作、开放包容、互学互鉴、互利共赢的丝绸之路精神。"]}]}, {"id": "u4_s5", "title": "全面深化改革阶段", "paras": [{"id": "u4_s5_p1", "buf": ["By 2012, China had entered a new phase of development, prioritising high-quality development and sustainable development. The shift towards a more balanced approach to economic development reflected China's cultural commitment to harmony and sustainability—concepts that have deep roots in China's ancient philosophy. The Belt and Road Initiative, launched in 2013, embodies this spirit by fostering international cooperation and trade while reinforcing China's commitment to mutual benefit and global partnerships, a concept that resonates with traditional Chinese notions of interdependence."], "text": "By 2012, China had entered a new phase of development, prioritising high-quality development and sustainable development. The shift towards a more balanced approach to economic development reflected China's cultural commitment to harmony and sustainability—concepts that have deep roots in China's ancient philosophy. The Belt and Road Initiative, launched in 2013, embodies this spirit by fostering international cooperation and trade while reinforcing China's commitment to mutual benefit and global partnerships, a concept that resonates with traditional Chinese notions of interdependence.", "chunks": ["By 2012, China had entered a new phase of development, prioritising high-quality development and sustainable development. The shift towards a more balanced approach to economic development reflected China's cultural commitment to harmony and sustainability—concepts that have deep roots in China's ancient philosophy. The Belt and Road Initiative, launched in 2013, embodies this spirit by fostering international cooperation and trade while reinforcing China's commitment to mutual benefit and global partnerships, a concept that resonates with traditional Chinese notions of interdependence."]}, {"id": "u4_s5_p2", "buf": ["In 2015, China introduced supply-side structural reform, which focused on optimising the economic structure, reducing inefficiencies, and ensuring long-term sustainability. The reform aimed to enhance the quality and efficiency of the supply system, further unleashing market vitality and stimulating social creativity. China's commitment to green development, including its pledge to achieve carbon neutrality by 2060, further highlights its pursuit of balanced growth and harmony with the environment. This emphasis holds a central position in Chinese philosophical traditions such as Daoism, which advocates living in harmony with nature."], "text": "In 2015, China introduced supply-side structural reform, which focused on optimising the economic structure, reducing inefficiencies, and ensuring long-term sustainability. The reform aimed to enhance the quality and efficiency of the supply system, further unleashing market vitality and stimulating social creativity. China's commitment to green development, including its pledge to achieve carbon neutrality by 2060, further highlights its pursuit of balanced growth and harmony with the environment. This emphasis holds a central position in Chinese philosophical traditions such as Daoism, which advocates living in harmony with nature.", "chunks": ["In 2015, China introduced supply-side structural reform, which focused on optimising the economic structure, reducing inefficiencies, and ensuring long-term sustainability. The reform aimed to enhance the quality and efficiency of the supply system, further unleashing market vitality and stimulating social creativity. China's commitment to green development, including its pledge to achieve carbon neutrality by 2060, further highlights its pursuit of balanced growth and harmony with the environment. This emphasis holds a central position in Chinese philosophical traditions such as Daoism, which advocates living in harmony with nature."]}]}, {"id": "u4_s6", "title": "改革开放的影响", "paras": [{"id": "u4_s6_p1", "buf": ["The reform and opening-up policy has not only transformed China's economy but also reshaped its social and cultural landscape. It encouraged open-mindedness and innovation, embraced diverse perspectives, and integrated modernisation into socialism with Chinese characteristics. Culturally, this era nurtured a far more vibrant scene as China's film, music, literature, and media industries blossomed alongside rapid scientific and technological advancement. Educational reforms further strengthened the nation's workforce, preparing it to thrive in an increasingly globalised world while remaining true to its core values of collective progress and social harmony."], "text": "The reform and opening-up policy has not only transformed China's economy but also reshaped its social and cultural landscape. It encouraged open-mindedness and innovation, embraced diverse perspectives, and integrated modernisation into socialism with Chinese characteristics. Culturally, this era nurtured a far more vibrant scene as China's film, music, literature, and media industries blossomed alongside rapid scientific and technological advancement. Educational reforms further strengthened the nation's workforce, preparing it to thrive in an increasingly globalised world while remaining true to its core values of collective progress and social harmony.", "chunks": ["The reform and opening-up policy has not only transformed China's economy but also reshaped its social and cultural landscape. It encouraged open-mindedness and innovation, embraced diverse perspectives, and integrated modernisation into socialism with Chinese characteristics. Culturally, this era nurtured a far more vibrant scene as China's film, music, literature, and media industries blossomed alongside rapid scientific and technological advancement. Educational reforms further strengthened the nation's workforce, preparing it to thrive in an increasingly globalised world while remaining true to its core values of collective progress and social harmony."]}]}, {"id": "u4_s7", "title": "Made in China (中国制造) and Intelligent Manufacturing in China (中国智造) \"中国制造\"与\"中国智造\"", "paras": [{"id": "u4_s7_p1", "buf": ["The rise of \"Made in China\" has been driven by the country's unique advantages, such as its large and cost-effective labour force and its growing domestic market. Following the launch of the reform and opening-up policy, China welcomed foreign investment and global trade, accelerating the growth of its manufacturing sector. Joining the WTO further boosted this development by attracting foreign companies looking for competitive production costs. By 2023, China had become a global manufacturing powerhouse, with its manufacturing output accounting for 35% of the world's total. It is predicted that China's industrial added value (工业增加值) will account for 45% of the global total by 2030. This sustained growth paved the way for intelligent manufacturing in China, leading to great achievements in this field. It also created millions of jobs, improved living standards, and supported social stability."], "text": "The rise of \"Made in China\" has been driven by the country's unique advantages, such as its large and cost-effective labour force and its growing domestic market. Following the launch of the reform and opening-up policy, China welcomed foreign investment and global trade, accelerating the growth of its manufacturing sector. Joining the WTO further boosted this development by attracting foreign companies looking for competitive production costs. By 2023, China had become a global manufacturing powerhouse, with its manufacturing output accounting for 35% of the world's total. It is predicted that China's industrial added value (工业增加值) will account for 45% of the global total by 2030. This sustained growth paved the way for intelligent manufacturing in China, leading to great achievements in this field. It also created millions of jobs, improved living standards, and supported social stability.", "chunks": ["The rise of \"Made in China\" has been driven by the country's unique advantages, such as its large and cost-effective labour force and its growing domestic market. Following the launch of the reform and opening-up policy, China welcomed foreign investment and global trade, accelerating the growth of its manufacturing sector. Joining the WTO further boosted this development by attracting foreign companies looking for competitive production costs. By 2023, China had become a global manufacturing powerhouse, with its manufacturing output accounting for 35% of the world's total. It is predicted that China's industrial added value (工业增加值) will account for 45% of the global total by 2030. This sustained growth paved the way for intelligent manufacturing in China, leading to great achievements in this field. It also created millions of jobs, improved living standards, and supported social stability."]}, {"id": "u4_s7_p2", "buf": ["Launched by the State Council in 2015, the Made in China 2025 initiative called for accelerating China's transformation from a manufacturing giant (制造大国) into a global manufacturing power (制造强国). Innovation in traditional manufacturing industries, driven by emerging technologies and the digital economy, is strengthening the foundation of China's intelligent manufacturing. Today, \"Made in China\" represents not just mass production but smart manufacturing, highlighting the country's evolving role on the global stage. This is the result of sustained economic reforms and technological progress, while also reflecting traditional Chinese values such as the spirit of craftsmanship and the pursuit of excellence."], "text": "Launched by the State Council in 2015, the Made in China 2025 initiative called for accelerating China's transformation from a manufacturing giant (制造大国) into a global manufacturing power (制造强国). Innovation in traditional manufacturing industries, driven by emerging technologies and the digital economy, is strengthening the foundation of China's intelligent manufacturing. Today, \"Made in China\" represents not just mass production but smart manufacturing, highlighting the country's evolving role on the global stage. This is the result of sustained economic reforms and technological progress, while also reflecting traditional Chinese values such as the spirit of craftsmanship and the pursuit of excellence.", "chunks": ["Launched by the State Council in 2015, the Made in China 2025 initiative called for accelerating China's transformation from a manufacturing giant (制造大国) into a global manufacturing power (制造强国). Innovation in traditional manufacturing industries, driven by emerging technologies and the digital economy, is strengthening the foundation of China's intelligent manufacturing. Today, \"Made in China\" represents not just mass production but smart manufacturing, highlighting the country's evolving role on the global stage. This is the result of sustained economic reforms and technological progress, while also reflecting traditional Chinese values such as the spirit of craftsmanship and the pursuit of excellence."]}]}, {"id": "u4_s8", "title": "航空航天智能制造", "paras": [{"id": "u4_s8_p1", "buf": ["China's aerospace intelligent manufacturing has been continuously driving the nation's space industry forward. On 29th April 2021, the Tianhe core module was successfully launched from the Wenchang Space Launch Site in Hainan, marking the full commencement of the in-orbit assembly and construction of the Chinese space station and symbolising China's official entry into a new era of independently built space stations."], "text": "China's aerospace intelligent manufacturing has been continuously driving the nation's space industry forward. On 29th April 2021, the Tianhe core module was successfully launched from the Wenchang Space Launch Site in Hainan, marking the full commencement of the in-orbit assembly and construction of the Chinese space station and symbolising China's official entry into a new era of independently built space stations.", "chunks": ["China's aerospace intelligent manufacturing has been continuously driving the nation's space industry forward. On 29th April 2021, the Tianhe core module was successfully launched from the Wenchang Space Launch Site in Hainan, marking the full commencement of the in-orbit assembly and construction of the Chinese space station and symbolising China's official entry into a new era of independently built space stations."]}, {"id": "u4_s8_p2", "buf": ["Serving as the station's \"intelligent brain\" and central hub, Tianhe performs the crucial functions of management and control, supporting the rendezvous, docking, and berthing of visiting spacecraft such as laboratory modules, crewed spacecraft, and cargo vehicles."], "text": "Serving as the station's \"intelligent brain\" and central hub, Tianhe performs the crucial functions of management and control, supporting the rendezvous, docking, and berthing of visiting spacecraft such as laboratory modules, crewed spacecraft, and cargo vehicles.", "chunks": ["Serving as the station's \"intelligent brain\" and central hub, Tianhe performs the crucial functions of management and control, supporting the rendezvous, docking, and berthing of visiting spacecraft such as laboratory modules, crewed spacecraft, and cargo vehicles."]}, {"id": "u4_s8_p3", "buf": ["As a masterpiece of cutting-edge science and engineering, the Tianhe core module integrates numerous domestically developed advanced technologies, demonstrating China's strong capabilities in space technology. Every component, from the smallest part to the overall structure, has undergone rigorous quality control to ensure high safety and reliability under the extreme conditions of space, setting a benchmark for the precision manufacturing of China's aerospace industry. Its modular, expandable design allows it to meet the diverse needs of future missions, showcasing the distinctive strengths of intelligent manufacturing in China."], "text": "As a masterpiece of cutting-edge science and engineering, the Tianhe core module integrates numerous domestically developed advanced technologies, demonstrating China's strong capabilities in space technology. Every component, from the smallest part to the overall structure, has undergone rigorous quality control to ensure high safety and reliability under the extreme conditions of space, setting a benchmark for the precision manufacturing of China's aerospace industry. Its modular, expandable design allows it to meet the diverse needs of future missions, showcasing the distinctive strengths of intelligent manufacturing in China.", "chunks": ["As a masterpiece of cutting-edge science and engineering, the Tianhe core module integrates numerous domestically developed advanced technologies, demonstrating China's strong capabilities in space technology. Every component, from the smallest part to the overall structure, has undergone rigorous quality control to ensure high safety and reliability under the extreme conditions of space, setting a benchmark for the precision manufacturing of China's aerospace industry. Its modular, expandable design allows it to meet the diverse needs of future missions, showcasing the distinctive strengths of intelligent manufacturing in China."]}]}, {"id": "u4_s9", "title": "中国新能源汽车产业的崛起", "paras": [{"id": "u4_s9_p1", "buf": ["In 2023, China's production of new energy vehicles reached 20 million units, demonstrating the strength of intelligent manufacturing in China. The Made in China 2025 initiative identifies the NEV industry as one of the key strategic sectors for breakthrough development. Achieving intelligent and highly automated production in automobile manufacturing will strongly advance the transformation from \"Made in China\" to intelligent manufacturing in China. NEVs represent the primary direction of global automotive transformation and green development, as well as China's strategic choice for promoting high-quality growth in its automotive industry."], "text": "In 2023, China's production of new energy vehicles reached 20 million units, demonstrating the strength of intelligent manufacturing in China. The Made in China 2025 initiative identifies the NEV industry as one of the key strategic sectors for breakthrough development. Achieving intelligent and highly automated production in automobile manufacturing will strongly advance the transformation from \"Made in China\" to intelligent manufacturing in China. NEVs represent the primary direction of global automotive transformation and green development, as well as China's strategic choice for promoting high-quality growth in its automotive industry.", "chunks": ["In 2023, China's production of new energy vehicles reached 20 million units, demonstrating the strength of intelligent manufacturing in China. The Made in China 2025 initiative identifies the NEV industry as one of the key strategic sectors for breakthrough development. Achieving intelligent and highly automated production in automobile manufacturing will strongly advance the transformation from \"Made in China\" to intelligent manufacturing in China. NEVs represent the primary direction of global automotive transformation and green development, as well as China's strategic choice for promoting high-quality growth in its automotive industry."]}, {"id": "u4_s9_p2", "buf": ["Power batteries are the core component of NEVs, and China's power-battery sector has achieved continuous breakthroughs in materials and new-technology applications. On the technological front, China has also achieved breakthroughs in various NEV-related technologies in recent years, significantly enhancing the overall level of vehicle intelligence."], "text": "Power batteries are the core component of NEVs, and China's power-battery sector has achieved continuous breakthroughs in materials and new-technology applications. On the technological front, China has also achieved breakthroughs in various NEV-related technologies in recent years, significantly enhancing the overall level of vehicle intelligence.", "chunks": ["Power batteries are the core component of NEVs, and China's power-battery sector has achieved continuous breakthroughs in materials and new-technology applications. On the technological front, China has also achieved breakthroughs in various NEV-related technologies in recent years, significantly enhancing the overall level of vehicle intelligence."]}, {"id": "u4_s9_p3", "buf": ["Today, China's intelligently made vehicles are rapidly entering the global market. Exports, particularly to traditionally advanced automotive markets, continue to expand, ushering in a new phase of worldwide competition and elevating China's automobile industry to a world-class level."], "text": "Today, China's intelligently made vehicles are rapidly entering the global market. Exports, particularly to traditionally advanced automotive markets, continue to expand, ushering in a new phase of worldwide competition and elevating China's automobile industry to a world-class level.", "chunks": ["Today, China's intelligently made vehicles are rapidly entering the global market. Exports, particularly to traditionally advanced automotive markets, continue to expand, ushering in a new phase of worldwide competition and elevating China's automobile industry to a world-class level."]}]}, {"id": "u4_s10", "title": "高铁", "paras": [{"id": "u4_s10_p1", "buf": ["China's high-speed rail network, the world's largest, is a testament to the country's engineering prowess and is supported by feats of intelligent manufacturing. A prime example is the Fuxing bullet train, which operates autonomously at 350 kilometres per hour on designated lines. Welding (焊接) is a key process in the manufacture of the train car bodies. Through digital management of the welding process, real-time data acquisition, automatic detection, and automated alarms enable continuous monitoring of the welding operation and effective process control, thereby ensuring higher welding quality."], "text": "China's high-speed rail network, the world's largest, is a testament to the country's engineering prowess and is supported by feats of intelligent manufacturing. A prime example is the Fuxing bullet train, which operates autonomously at 350 kilometres per hour on designated lines. Welding (焊接) is a key process in the manufacture of the train car bodies. Through digital management of the welding process, real-time data acquisition, automatic detection, and automated alarms enable continuous monitoring of the welding operation and effective process control, thereby ensuring higher welding quality.", "chunks": ["China's high-speed rail network, the world's largest, is a testament to the country's engineering prowess and is supported by feats of intelligent manufacturing. A prime example is the Fuxing bullet train, which operates autonomously at 350 kilometres per hour on designated lines. Welding (焊接) is a key process in the manufacture of the train car bodies. Through digital management of the welding process, real-time data acquisition, automatic detection, and automated alarms enable continuous monitoring of the welding operation and effective process control, thereby ensuring higher welding quality."]}, {"id": "u4_s10_p2", "buf": ["HSR has fuelled domestic economic growth and enhanced connectivity. In addition to achieving strong domestic development, China has also exported its HSR expertise, investing in overseas infrastructure projects, strengthening economic partnerships, and fostering cultural exchange. As China continues to develop its HSR capabilities, it exemplifies how intelligent manufacturing can drive national development and foster international collaboration."], "text": "HSR has fuelled domestic economic growth and enhanced connectivity. In addition to achieving strong domestic development, China has also exported its HSR expertise, investing in overseas infrastructure projects, strengthening economic partnerships, and fostering cultural exchange. As China continues to develop its HSR capabilities, it exemplifies how intelligent manufacturing can drive national development and foster international collaboration.", "chunks": ["HSR has fuelled domestic economic growth and enhanced connectivity. In addition to achieving strong domestic development, China has also exported its HSR expertise, investing in overseas infrastructure projects, strengthening economic partnerships, and fostering cultural exchange. As China continues to develop its HSR capabilities, it exemplifies how intelligent manufacturing can drive national development and foster international collaboration."]}]}, {"id": "u4_s11", "title": "中国数字经济", "paras": [{"id": "u4_s11_p1", "buf": ["China's digital economy has evolved through three distinct stages. The first, from 1994 to 2004, was the incubation stage, when the commercial internet began to take shape, and a number of domestic internet enterprises emerged, laying the foundation for China's digital-economy framework. The second stage, from 2005 to 2015, was marked by explosive growth driven by e-commerce, online banking, web portals, and the gaming industry, propelling the digital economy into a period of rapid expansion. Since 2016, China has entered the stage of integration and coordination, characterised by the deep integration of digital technologies with the real economy at home and active participation in digital-economy governance abroad."], "text": "China's digital economy has evolved through three distinct stages. The first, from 1994 to 2004, was the incubation stage, when the commercial internet began to take shape, and a number of domestic internet enterprises emerged, laying the foundation for China's digital-economy framework. The second stage, from 2005 to 2015, was marked by explosive growth driven by e-commerce, online banking, web portals, and the gaming industry, propelling the digital economy into a period of rapid expansion. Since 2016, China has entered the stage of integration and coordination, characterised by the deep integration of digital technologies with the real economy at home and active participation in digital-economy governance abroad.", "chunks": ["China's digital economy has evolved through three distinct stages. The first, from 1994 to 2004, was the incubation stage, when the commercial internet began to take shape, and a number of domestic internet enterprises emerged, laying the foundation for China's digital-economy framework. The second stage, from 2005 to 2015, was marked by explosive growth driven by e-commerce, online banking, web portals, and the gaming industry, propelling the digital economy into a period of rapid expansion. Since 2016, China has entered the stage of integration and coordination, characterised by the deep integration of digital technologies with the real economy at home and active participation in digital-economy governance abroad."]}]}, {"id": "u4_s12", "title": "数字基础设施建设", "paras": [{"id": "u4_s12_p1", "buf": ["China has made unprecedented progress in building its digital infrastructure, laying the foundation for technological advancements and economic growth. The country leads the world in both the number of 5G base stations and mobile data usage, with its network infrastructure being the largest and most extensive globally. High-speed internet access is widespread, supported by a vast network of optical fibre cables."], "text": "China has made unprecedented progress in building its digital infrastructure, laying the foundation for technological advancements and economic growth. The country leads the world in both the number of 5G base stations and mobile data usage, with its network infrastructure being the largest and most extensive globally. High-speed internet access is widespread, supported by a vast network of optical fibre cables.", "chunks": ["China has made unprecedented progress in building its digital infrastructure, laying the foundation for technological advancements and economic growth. The country leads the world in both the number of 5G base stations and mobile data usage, with its network infrastructure being the largest and most extensive globally. High-speed internet access is widespread, supported by a vast network of optical fibre cables."]}, {"id": "u4_s12_p2", "buf": ["China's digital infrastructure also involves intelligent transportation systems and the development of smart cities, which have significantly improved efficiency in urban mobility and the delivery of public services. The government's focus on smart urbanisation aligns with the goal of harmonious and livable urban development, where technological advancements are expected to promote not only economic growth but also social well-being."], "text": "China's digital infrastructure also involves intelligent transportation systems and the development of smart cities, which have significantly improved efficiency in urban mobility and the delivery of public services. The government's focus on smart urbanisation aligns with the goal of harmonious and livable urban development, where technological advancements are expected to promote not only economic growth but also social well-being.", "chunks": ["China's digital infrastructure also involves intelligent transportation systems and the development of smart cities, which have significantly improved efficiency in urban mobility and the delivery of public services. The government's focus on smart urbanisation aligns with the goal of harmonious and livable urban development, where technological advancements are expected to promote not only economic growth but also social well-being."]}]}, {"id": "u4_s13", "title": "数字经济的核心领域", "paras": [{"id": "u4_s13_p1", "buf": ["The digital economy has transformed various sectors, creating new opportunities and changing the way businesses operate and people interact. Key drivers of this shift include e-commerce, the sharing economy, and mobile payments."], "text": "The digital economy has transformed various sectors, creating new opportunities and changing the way businesses operate and people interact. Key drivers of this shift include e-commerce, the sharing economy, and mobile payments.", "chunks": ["The digital economy has transformed various sectors, creating new opportunities and changing the way businesses operate and people interact. Key drivers of this shift include e-commerce, the sharing economy, and mobile payments."]}, {"id": "u4_s13_p2", "buf": ["E-commerce in China has revolutionised retail, driven by the rapidly growing consumer base and widespread internet access. Some platforms have become integral to daily life, expanding product availability and enabling businesses to reach consumers nationwide. This transformation emphasises practicality, as technology is utilised to address concrete, real-world needs. Additionally, e-commerce has significantly reduced the urban-rural divide, providing farmers and local producers with direct access to broader markets, thereby increasing their incomes and promoting regional development. Thus, e-commerce represents more than a commercial revolution; it has become a driver for inclusive growth and balanced regional development, embodying China's broader vision of shared prosperity."], "text": "E-commerce in China has revolutionised retail, driven by the rapidly growing consumer base and widespread internet access. Some platforms have become integral to daily life, expanding product availability and enabling businesses to reach consumers nationwide. This transformation emphasises practicality, as technology is utilised to address concrete, real-world needs. Additionally, e-commerce has significantly reduced the urban-rural divide, providing farmers and local producers with direct access to broader markets, thereby increasing their incomes and promoting regional development. Thus, e-commerce represents more than a commercial revolution; it has become a driver for inclusive growth and balanced regional development, embodying China's broader vision of shared prosperity.", "chunks": ["E-commerce in China has revolutionised retail, driven by the rapidly growing consumer base and widespread internet access. Some platforms have become integral to daily life, expanding product availability and enabling businesses to reach consumers nationwide. This transformation emphasises practicality, as technology is utilised to address concrete, real-world needs. Additionally, e-commerce has significantly reduced the urban-rural divide, providing farmers and local producers with direct access to broader markets, thereby increasing their incomes and promoting regional development. Thus, e-commerce represents more than a commercial revolution; it has become a driver for inclusive growth and balanced regional development, embodying China's broader vision of shared prosperity."]}, {"id": "u4_s13_p3", "buf": ["China's sharing economy, driven by platforms like bike-sharing and car-sharing services, is transforming how people access goods and services. By maximising resource utilisation and reducing dependence on personal ownership, the sharing economy aligns with principles of sustainability and resource efficiency. These platforms lower costs and promote more efficient resource use, embodying cultural values of conservation and harmony with the environment. Additionally, the sharing economy has made many previously expensive products and services accessible to a wider range of consumers, further strengthening the values of community and mutual benefit."], "text": "China's sharing economy, driven by platforms like bike-sharing and car-sharing services, is transforming how people access goods and services. By maximising resource utilisation and reducing dependence on personal ownership, the sharing economy aligns with principles of sustainability and resource efficiency. These platforms lower costs and promote more efficient resource use, embodying cultural values of conservation and harmony with the environment. Additionally, the sharing economy has made many previously expensive products and services accessible to a wider range of consumers, further strengthening the values of community and mutual benefit.", "chunks": ["China's sharing economy, driven by platforms like bike-sharing and car-sharing services, is transforming how people access goods and services. By maximising resource utilisation and reducing dependence on personal ownership, the sharing economy aligns with principles of sustainability and resource efficiency. These platforms lower costs and promote more efficient resource use, embodying cultural values of conservation and harmony with the environment. Additionally, the sharing economy has made many previously expensive products and services accessible to a wider range of consumers, further strengthening the values of community and mutual benefit."]}, {"id": "u4_s13_p4", "buf": ["Mobile payments, with the highest adoption rate in the world, have become an integral part of daily life in China, enabling fast and secure transactions across retail, transportation, and beyond. This widespread use is driven by strong consumer preferences for convenience and security. These payment systems are not just technological innovations; they reflect a societal reliance on efficient, secure, and accessible financial transactions. Moreover, mobile payments facilitate smoother interactions between businesses and consumers, significantly contributing to the digital transformation of traditional industries."], "text": "Mobile payments, with the highest adoption rate in the world, have become an integral part of daily life in China, enabling fast and secure transactions across retail, transportation, and beyond. This widespread use is driven by strong consumer preferences for convenience and security. These payment systems are not just technological innovations; they reflect a societal reliance on efficient, secure, and accessible financial transactions. Moreover, mobile payments facilitate smoother interactions between businesses and consumers, significantly contributing to the digital transformation of traditional industries.", "chunks": ["Mobile payments, with the highest adoption rate in the world, have become an integral part of daily life in China, enabling fast and secure transactions across retail, transportation, and beyond. This widespread use is driven by strong consumer preferences for convenience and security. These payment systems are not just technological innovations; they reflect a societal reliance on efficient, secure, and accessible financial transactions. Moreover, mobile payments facilitate smoother interactions between businesses and consumers, significantly contributing to the digital transformation of traditional industries."]}]}, {"id": "u4_s14", "title": "中国绿色发展", "paras": [{"id": "u4_s14_p1", "buf": ["A healthy ecological environment is the foundation for a better life and a shared aspiration of humanity. Green development seeks harmony between people and nature, achieving maximum social and economic benefits with minimal resource consumption and environmental impact. It represents sustainable, high-quality progress and has become a common goal for all nations."], "text": "A healthy ecological environment is the foundation for a better life and a shared aspiration of humanity. Green development seeks harmony between people and nature, achieving maximum social and economic benefits with minimal resource consumption and environmental impact. It represents sustainable, high-quality progress and has become a common goal for all nations.", "chunks": ["A healthy ecological environment is the foundation for a better life and a shared aspiration of humanity. Green development seeks harmony between people and nature, achieving maximum social and economic benefits with minimal resource consumption and environmental impact. It represents sustainable, high-quality progress and has become a common goal for all nations."]}, {"id": "u4_s14_p2", "buf": ["The concept of \"harmony between humanity and nature\" is a defining feature of Chinese civilisation. Respect for nature and dedication to protecting it have ensured the survival and prosperity of the Chinese nation for thousands of years. To advance ecological civilisation, China has made resource conservation and environmental protection a basic national policy and has adopted sustainable development as a national strategy since the beginning of reform and opening up."], "text": "The concept of \"harmony between humanity and nature\" is a defining feature of Chinese civilisation. Respect for nature and dedication to protecting it have ensured the survival and prosperity of the Chinese nation for thousands of years. To advance ecological civilisation, China has made resource conservation and environmental protection a basic national policy and has adopted sustainable development as a national strategy since the beginning of reform and opening up.", "chunks": ["The concept of \"harmony between humanity and nature\" is a defining feature of Chinese civilisation. Respect for nature and dedication to protecting it have ensured the survival and prosperity of the Chinese nation for thousands of years. To advance ecological civilisation, China has made resource conservation and environmental protection a basic national policy and has adopted sustainable development as a national strategy since the beginning of reform and opening up."]}, {"id": "u4_s14_p3", "buf": ["China's green development strategy is driven by the ambitious \"dual carbon\" goals of reaching peak carbon emissions by 2030 and achieving carbon neutrality by 2060. This initiative accelerates the development of low-carbon technologies and reinforces China's active role in global climate governance. The 20th CPC National Congress underscored the idea that respecting and protecting nature is essential for building a modern socialist country. By advancing the Beautiful China Initiative, China aims to build a sustainable, resilient economy that maintains harmony between humanity and nature, securing long-term prosperity for its people."], "text": "China's green development strategy is driven by the ambitious \"dual carbon\" goals of reaching peak carbon emissions by 2030 and achieving carbon neutrality by 2060. This initiative accelerates the development of low-carbon technologies and reinforces China's active role in global climate governance. The 20th CPC National Congress underscored the idea that respecting and protecting nature is essential for building a modern socialist country. By advancing the Beautiful China Initiative, China aims to build a sustainable, resilient economy that maintains harmony between humanity and nature, securing long-term prosperity for its people.", "chunks": ["China's green development strategy is driven by the ambitious \"dual carbon\" goals of reaching peak carbon emissions by 2030 and achieving carbon neutrality by 2060. This initiative accelerates the development of low-carbon technologies and reinforces China's active role in global climate governance. The 20th CPC National Congress underscored the idea that respecting and protecting nature is essential for building a modern socialist country. By advancing the Beautiful China Initiative, China aims to build a sustainable, resilient economy that maintains harmony between humanity and nature, securing long-term prosperity for its people."]}, {"id": "u4_s14_p4", "buf": ["the Beautiful China Initiative: The concept of Beautiful China was put forward at the 18th National Congress of the Communist Party of China. It emphasises placing ecological civilisation building in a prominent position and integrating it into all aspects and the entire process of economic, political, cultural, and social development. The assessment index system includes five categories of indicators: clean air, clear water, safe soil, sound ecosystems, and neat and livable human settlements. \"美丽中国\"是中国共产党第十八次全国代表大会提出的概念，强调把生态文明建设放在突出地位，融入经济建设、政治建设、文化建设、社会建设各方面和全过程。美丽中国建设评估指标体系包括空气清新、水体洁净、土壤安全、生态良好、人居整洁五类指标。"], "text": "the Beautiful China Initiative: The concept of Beautiful China was put forward at the 18th National Congress of the Communist Party of China. It emphasises placing ecological civilisation building in a prominent position and integrating it into all aspects and the entire process of economic, political, cultural, and social development. The assessment index system includes five categories of indicators: clean air, clear water, safe soil, sound ecosystems, and neat and livable human settlements. \"美丽中国\"是中国共产党第十八次全国代表大会提出的概念，强调把生态文明建设放在突出地位，融入经济建设、政治建设、文化建设、社会建设各方面和全过程。美丽中国建设评估指标体系包括空气清新、水体洁净、土壤安全、生态良好、人居整洁五类指标。", "chunks": ["the Beautiful China Initiative: The concept of Beautiful China was put forward at the 18th National Congress of the Communist Party of China. It emphasises placing ecological civilisation building in a prominent position and integrating it into all aspects and the entire process of economic, political, cultural, and social development. The assessment index system includes five categories of indicators: clean air, clear water, safe soil, sound ecosystems, and neat and livable human settlements. \"美丽中国\"是中国共产党第十八次全国代表大会提出的概念，强调把生态文明建设放在突出地位，融入经济建设、政治建设、文化建设、社会建设各方面和全过程。美丽中国建设评估指标体系包括空气清新、水体洁净、土壤安全、生态良好、人居整洁五类指标。"]}, {"id": "u4_s14_p5", "buf": ["Through a series of targeted policies that cover ecological conservation, energy transformation, technological innovation, and the promotion of sustainable lifestyles, China is reshaping its socio-economic landscape to address environmental challenges and build an ecological civilisation for the future. These initiatives reflect China's commitment to integrating sustainability into its socio-economic framework, supporting its long-term goal of building an ecological civilisation."], "text": "Through a series of targeted policies that cover ecological conservation, energy transformation, technological innovation, and the promotion of sustainable lifestyles, China is reshaping its socio-economic landscape to address environmental challenges and build an ecological civilisation for the future. These initiatives reflect China's commitment to integrating sustainability into its socio-economic framework, supporting its long-term goal of building an ecological civilisation.", "chunks": ["Through a series of targeted policies that cover ecological conservation, energy transformation, technological innovation, and the promotion of sustainable lifestyles, China is reshaping its socio-economic landscape to address environmental challenges and build an ecological civilisation for the future. These initiatives reflect China's commitment to integrating sustainability into its socio-economic framework, supporting its long-term goal of building an ecological civilisation."]}]}, {"id": "u4_s15", "title": "生态保护与修复", "paras": [{"id": "u4_s15_p1", "buf": ["China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodiversity and promotes ecotourism in national parks such as those of Zhangjiajie (张家界) and Pudacuo (普达措). The \"Green Shield\" initiative (\"绿盾\"行动) focuses on reinforcing reforestation in areas like the Loess Plateau and the Taihang Mountains, reversing desertification and improving soil quality. Additionally, President Xi Jinping's Two Mountains Theory (\"两山\"理念) emphasises that \"lucid waters and lush mountains are invaluable assets\". This theory encourages the balancing of economic growth with environmental protection through practices such as organic farming and agroforestry (农林复合经营)."], "text": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodiversity and promotes ecotourism in national parks such as those of Zhangjiajie (张家界) and Pudacuo (普达措). The \"Green Shield\" initiative (\"绿盾\"行动) focuses on reinforcing reforestation in areas like the Loess Plateau and the Taihang Mountains, reversing desertification and improving soil quality. Additionally, President Xi Jinping's Two Mountains Theory (\"两山\"理念) emphasises that \"lucid waters and lush mountains are invaluable assets\". This theory encourages the balancing of economic growth with environmental protection through practices such as organic farming and agroforestry (农林复合经营).", "chunks": ["China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodiversity and promotes ecotourism in national parks such as those of Zhangjiajie (张家界) and Pudacuo (普达措). The \"Green Shield\" initiative (\"绿盾\"行动) focuses on reinforcing reforestation in areas like the Loess Plateau and the Taihang Mountains, reversing desertification and improving soil quality. Additionally, President Xi Jinping's Two Mountains Theory (\"两山\"理念) emphasises that \"lucid waters and lush mountains are invaluable assets\". This theory encourages the balancing of economic growth with environmental protection through practices such as organic farming and agroforestry (农林复合经营)."]}]}, {"id": "u4_s16", "title": "能源结构调整与优化", "paras": [{"id": "u4_s16_p1", "buf": ["To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with its generation capacity exceeding 500 gigawatts (千兆瓦). Under the 14th Five-Year Plan (2021—2025), China aimed to have non-fossil energy account for 20% of total energy consumption by 2025, and the target has been exceeded. Through ongoing investments in smart grids and ultra-high-voltage direct current (特高压直流电) transmission systems, China is strengthening its energy infrastructure, improving energy distribution, and integrating renewable sources more efficiently."], "text": "To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with its generation capacity exceeding 500 gigawatts (千兆瓦). Under the 14th Five-Year Plan (2021—2025), China aimed to have non-fossil energy account for 20% of total energy consumption by 2025, and the target has been exceeded. Through ongoing investments in smart grids and ultra-high-voltage direct current (特高压直流电) transmission systems, China is strengthening its energy infrastructure, improving energy distribution, and integrating renewable sources more efficiently.", "chunks": ["To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with its generation capacity exceeding 500 gigawatts (千兆瓦). Under the 14th Five-Year Plan (2021—2025), China aimed to have non-fossil energy account for 20% of total energy consumption by 2025, and the target has been exceeded. Through ongoing investments in smart grids and ultra-high-voltage direct current (特高压直流电) transmission systems, China is strengthening its energy infrastructure, improving energy distribution, and integrating renewable sources more efficiently."]}]}, {"id": "u4_s17", "title": "绿色技术与循环经济", "paras": [{"id": "u4_s17_p1", "buf": ["China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy, which focuses on recycling, reusing, and reducing resource consumption. The 13th Five-Year Plan (2016—2020) included a dedicated plan for the development of a circular economy, which targets waste reduction and resource efficiency. Municipal programmes, such as Shanghai's trash-sorting campaign, have helped reduce landfill use and create new jobs in recycling. The \"green credit\" policy provides financial support for industries adopting circular economy practices, while industrial symbiosis encourages the reuse of waste materials across sectors to enhance sustainability."], "text": "China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy, which focuses on recycling, reusing, and reducing resource consumption. The 13th Five-Year Plan (2016—2020) included a dedicated plan for the development of a circular economy, which targets waste reduction and resource efficiency. Municipal programmes, such as Shanghai's trash-sorting campaign, have helped reduce landfill use and create new jobs in recycling. The \"green credit\" policy provides financial support for industries adopting circular economy practices, while industrial symbiosis encourages the reuse of waste materials across sectors to enhance sustainability.", "chunks": ["China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy, which focuses on recycling, reusing, and reducing resource consumption. The 13th Five-Year Plan (2016—2020) included a dedicated plan for the development of a circular economy, which targets waste reduction and resource efficiency. Municipal programmes, such as Shanghai's trash-sorting campaign, have helped reduce landfill use and create new jobs in recycling. The \"green credit\" policy provides financial support for industries adopting circular economy practices, while industrial symbiosis encourages the reuse of waste materials across sectors to enhance sustainability."]}]}, {"id": "u4_s18", "title": "绿色生活方式的推广", "paras": [{"id": "u4_s18_p1", "buf": ["Promoting sustainable lifestyles is key to China's green development agenda. Public campaigns educate people on reducing plastic use, conserving energy, and choosing public transport or bicycles to raise environmental awareness in schools and communities. Cities are expanding bike-sharing networks and public transit options, and eco-friendly purchases are widely encouraged. The government also collaborates with non-governmental organisations and local communities to foster a culture of sustainability, engaging citizens in environmental protection efforts."], "text": "Promoting sustainable lifestyles is key to China's green development agenda. Public campaigns educate people on reducing plastic use, conserving energy, and choosing public transport or bicycles to raise environmental awareness in schools and communities. Cities are expanding bike-sharing networks and public transit options, and eco-friendly purchases are widely encouraged. The government also collaborates with non-governmental organisations and local communities to foster a culture of sustainability, engaging citizens in environmental protection efforts.", "chunks": ["Promoting sustainable lifestyles is key to China's green development agenda. Public campaigns educate people on reducing plastic use, conserving energy, and choosing public transport or bicycles to raise environmental awareness in schools and communities. Cities are expanding bike-sharing networks and public transit options, and eco-friendly purchases are widely encouraged. The government also collaborates with non-governmental organisations and local communities to foster a culture of sustainability, engaging citizens in environmental protection efforts."]}]}]}], "vocabA": [{"term": "Confucianism", "zh": "儒家", "q": "Traditional Chinese economic thought has always been deeply intertwined with the country's philosophical traditions. Confucianism, Daoism, and Legalism complemented one another and together shaped eco", "tr": "中国的传统经济思想始终与国家的哲学传统紧密交织。儒家、道家与法家思想相互补充，共同塑造了经济实践与社会行为。这些哲学为商业活动提供了各具特色的框架，也影响了中国经济历史的进程。", "pos": "术语", "src": "原文"}, {"term": "Daoism", "zh": "道家", "q": "Traditional Chinese economic thought has always been deeply intertwined with the country's philosophical traditions. Confucianism, Daoism, and Legalism complemented one another and together shaped eco", "tr": "中国的传统经济思想始终与国家的哲学传统紧密交织。儒家、道家与法家思想相互补充，共同塑造了经济实践与社会行为。这些哲学为商业活动提供了各具特色的框架，也影响了中国经济历史的进程。", "pos": "术语", "src": "原文"}, {"term": "Legalism", "zh": "法家", "q": "Traditional Chinese economic thought has always been deeply intertwined with the country's philosophical traditions. Confucianism, Daoism, and Legalism complemented one another and together shaped eco", "tr": "中国的传统经济思想始终与国家的哲学传统紧密交织。儒家、道家与法家思想相互补充，共同塑造了经济实践与社会行为。这些哲学为商业活动提供了各具特色的框架，也影响了中国经济历史的进程。", "pos": "术语", "src": "原文"}, {"term": "non-action", "zh": "无为", "q": "In the economic sphere, the Daoist principle of non-action is often interpreted as acting in accordance with market principles and refraining from arbitrary or reckless intervention. In agricultural p", "tr": "在经济领域，道家“无为”的主张常被理解为顺应市场规律行事，避免任意或轻率的干预。在农业实践中，道家主张尊重自然的生机与创造力，与自然和谐相处。农民顺应自然节律劳作，以确保收成可持续，同时避免过度开发资源。", "pos": "术语", "src": "原文"}, {"term": "harmony with nature", "zh": "天人和谐", "q": "In 2015, China introduced supply-side structural reform, which focused on optimising the economic structure, reducing inefficiencies, and ensuring long-term sustainability. The reform aimed to enhance", "tr": "2015年，中国提出供给侧结构性改革，着力优化经济结构、减少低效供给、确保长期可持续。改革旨在提高供给体系的质量和效率，进一步释放市场活力、激发社会创造力。中国致力于绿色发展，包括承诺在2060年前实现碳中和，进一步彰显了其对均衡增长、与环境和睦相处的追求。这一理念在中国道家的哲学传统中占据核心地位，道家主张与自然和谐相处。", "pos": "术语", "src": "原文"}, {"term": "reform and opening up", "zh": "改革开放", "q": "the Third Plenary Session of the 11th CPC Central Committee: Held in Beijing in December 1978, this key meeting marked the start of China's economic reforms. Led by Deng Xiaoping, it set the focus of ", "tr": "中国共产党第十一届中央委员会第三次全体会议，于1978年12月在北京举行。这次关键会议标志着中国经济改革的开始。在邓小平的领导下，会议将党和国家的工作重点放在经济建设上，开启了从计划经济向市场经济的转型，为中国的现代化进程和改革开放奠定了基础。", "pos": "术语", "src": "原文"}, {"term": "socialist market economy", "zh": "社会主义市场经济", "q": "In 1978, the Third Plenary Session of the 11th CPC Central Committee marked a pivotal moment in China's history, as the country began to embrace reform and opening up. Reform seeks to fundamentally re", "tr": "1978年，党的十一届三中全会成为中国历史上一个关键的时刻，国家由此开始实行改革开放。改革旨在从根本上重塑曾束缚生产力发展的经济体制，建立并完善社会主义市场经济，同时推进政治体制及其他制度领域的相关变革，以确保各方面协调推进；对外开放则着眼对外交往——在经济全球化条件下积极参与国际合作与竞争，扩大同各国的交流，借鉴人类文明的优秀成果，促进中国的发展与现代化。", "pos": "术语", "src": "原文"}, {"term": "comprehensively deepening reform", "zh": "全面深化改革", "q": "", "tr": "", "pos": "制度", "src": "原文"}, {"term": "Belt and Road Initiative", "zh": "一带一路", "q": "the Belt and Road Initiative: In 2013, President Xi Jinping raised the initiatives of joining with others to build a Silk Road Economic Belt and a 21st Century Maritime Silk Road, known collectively a", "tr": "“一带一路”倡议。2013年，习近平主席提出共同建设“丝绸之路经济带”和“21世纪海上丝绸之路”的重大倡议，即共建“一带一路”倡议。“一带一路”倡议秉持和平合作、开放包容、互学互鉴、互利共赢的丝绸之路精神。", "pos": "术语", "src": "原文"}, {"term": "Silk Road Economic Belt", "zh": "丝绸之路经济带", "q": "the Belt and Road Initiative: In 2013, President Xi Jinping raised the initiatives of joining with others to build a Silk Road Economic Belt and a 21st Century Maritime Silk Road, known collectively a", "tr": "“一带一路”倡议。2013年，习近平主席提出共同建设“丝绸之路经济带”和“21世纪海上丝绸之路”的重大倡议，即共建“一带一路”倡议。“一带一路”倡议秉持和平合作、开放包容、互学互鉴、互利共赢的丝绸之路精神。", "pos": "术语", "src": "原文"}, {"term": "21st Century Maritime Silk Road", "zh": "21世纪海上丝绸之路", "q": "the Belt and Road Initiative: In 2013, President Xi Jinping raised the initiatives of joining with others to build a Silk Road Economic Belt and a 21st Century Maritime Silk Road, known collectively a", "tr": "“一带一路”倡议。2013年，习近平主席提出共同建设“丝绸之路经济带”和“21世纪海上丝绸之路”的重大倡议，即共建“一带一路”倡议。“一带一路”倡议秉持和平合作、开放包容、互学互鉴、互利共赢的丝绸之路精神。", "pos": "术语", "src": "原文"}, {"term": "Silk Road", "zh": "丝绸之路", "q": "The intersection of economic philosophy and historical commercial activity is most evident in China's trade networks, particularly along the Silk Road. Established during the Han Dynasty, the ancient ", "tr": "经济哲学与历史商业活动的交汇，在中国的贸易网络，尤其是丝绸之路沿线，体现得最为明显。古老的丝绸之路始建于汉代，是一个连接中国与亚洲、欧洲和非洲各地的庞大贸易路线网络。汉唐时期，中国经历了前所未有的社会与经济繁荣。这种显著的繁荣使中国成为丝绸之路发展的主导力量，也体现了儒家关于社会责任的理想。历代中国政府也在丝绸之路的发展中发挥了不可或缺的作用。它们通过设置官职、制定法律政策、加强制度治理，为贸易提供了规制基础——这正是法家厉行法治、强化治理主张的实际体现。", "pos": "术语", "src": "原文"}, {"term": "World Trade Organization (WTO)", "zh": "世界贸易组织", "q": "China's accession (正式加入) to the World Trade Organization (WTO) marked a transformative moment in the nation's economic development. It enabled China to enhance its international standing and adhere to", "tr": "中国正式加入世界贸易组织，标志着其经济发展中一个具有转折意义的时刻。这使中国得以提升国际地位、遵循全球贸易规则。这一里程碑给中国和全球经济都带来了深刻变革。中国举世瞩目的增长得到广泛认可，其不断扩大开放的市场为中国和世界经济创造了互利共赢的局面。中国加入世界贸易组织后，与全球经济的融合进一步加深，掀起了新的外商投资热潮。中国的对外开放由政策导向阶段迈向制度导向阶段：过去主要依靠试点举措和行政指令推进，如今已发展成为以健全法律框架为基础、可预期的规则化开放体系。在这一阶段，中国经历了快速的工业化和城镇化，重塑了其经济与社会面貌。", "pos": "机构", "src": "原文"}, {"term": "accession", "zh": "正式加入", "q": "China's accession (正式加入) to the World Trade Organization (WTO) marked a transformative moment in the nation's economic development. It enabled China to enhance its international standing and adhere to", "tr": "中国正式加入世界贸易组织，标志着其经济发展中一个具有转折意义的时刻。这使中国得以提升国际地位、遵循全球贸易规则。这一里程碑给中国和全球经济都带来了深刻变革。中国举世瞩目的增长得到广泛认可，其不断扩大开放的市场为中国和世界经济创造了互利共赢的局面。中国加入世界贸易组织后，与全球经济的融合进一步加深，掀起了新的外商投资热潮。中国的对外开放由政策导向阶段迈向制度导向阶段：过去主要依靠试点举措和行政指令推进，如今已发展成为以健全法律框架为基础、可预期的规则化开放体系。在这一阶段，中国经历了快速的工业化和城镇化，重塑了其经济与社会面貌。", "pos": "术语", "src": "原文"}, {"term": "Made in China", "zh": "中国制造", "q": "The rise of \"Made in China\" has been driven by the country's unique advantages, such as its large and cost-effective labour force and its growing domestic market. Following the launch of the reform an", "tr": "中国制造的崛起，得益于中国独有的优势，例如规模庞大且成本低廉的劳动力以及不断扩大的国内市场。改革开放政策实施后，中国欢迎外商投资和全球贸易，加快了制造业的增长。加入世界贸易组织又通过吸引寻求低成本生产优势的外国企业，进一步推动了这一发展。到2023年，中国已成为全球制造业大国，制造业产值占全球总量的35%。据预测，到2030年，中国工业增加值将占全球总量的45%。这种持续增长为中国智能制造铺平了道路，使这一领域取得了巨大成就。它还创造了数百万个就业岗位，提高了生活水平，支撑了社会稳定。", "pos": "术语", "src": "原文"}, {"term": "Intelligent Manufacturing in China", "zh": "中国智造", "q": "The rise of \"Made in China\" has been driven by the country's unique advantages, such as its large and cost-effective labour force and its growing domestic market. Following the launch of the reform an", "tr": "中国制造的崛起，得益于中国独有的优势，例如规模庞大且成本低廉的劳动力以及不断扩大的国内市场。改革开放政策实施后，中国欢迎外商投资和全球贸易，加快了制造业的增长。加入世界贸易组织又通过吸引寻求低成本生产优势的外国企业，进一步推动了这一发展。到2023年，中国已成为全球制造业大国，制造业产值占全球总量的35%。据预测，到2030年，中国工业增加值将占全球总量的45%。这种持续增长为中国智能制造铺平了道路，使这一领域取得了巨大成就。它还创造了数百万个就业岗位，提高了生活水平，支撑了社会稳定。", "pos": "术语", "src": "原文"}, {"term": "industrial added value", "zh": "工业增加值", "q": "The rise of \"Made in China\" has been driven by the country's unique advantages, such as its large and cost-effective labour force and its growing domestic market. Following the launch of the reform an", "tr": "中国制造的崛起，得益于中国独有的优势，例如规模庞大且成本低廉的劳动力以及不断扩大的国内市场。改革开放政策实施后，中国欢迎外商投资和全球贸易，加快了制造业的增长。加入世界贸易组织又通过吸引寻求低成本生产优势的外国企业，进一步推动了这一发展。到2023年，中国已成为全球制造业大国，制造业产值占全球总量的35%。据预测，到2030年，中国工业增加值将占全球总量的45%。这种持续增长为中国智能制造铺平了道路，使这一领域取得了巨大成就。它还创造了数百万个就业岗位，提高了生活水平，支撑了社会稳定。", "pos": "术语", "src": "原文"}, {"term": "manufacturing giant", "zh": "制造大国", "q": "Launched by the State Council in 2015, the Made in China 2025 initiative called for accelerating China's transformation from a manufacturing giant (制造大国) into a global manufacturing power (制造强国). Inno", "tr": "2015年，国务院启动《中国制造2025》，提出加快中国从制造大国向制造强国转变。在新兴技术和数字经济的驱动下，传统制造业的创新正在夯实中国智能制造的基础。今天，“中国制造”不仅意味着大规模生产，更意味着智能制造，凸显出中国在全球舞台上不断变化的角色。这既是持续的经济改革和技术进步的结果，也体现了精益求精、追求卓越等中国传统价值观。", "pos": "术语", "src": "原文"}, {"term": "global manufacturing power", "zh": "制造强国", "q": "Launched by the State Council in 2015, the Made in China 2025 initiative called for accelerating China's transformation from a manufacturing giant (制造大国) into a global manufacturing power (制造强国). Inno", "tr": "2015年，国务院启动《中国制造2025》，提出加快中国从制造大国向制造强国转变。在新兴技术和数字经济的驱动下，传统制造业的创新正在夯实中国智能制造的基础。今天，“中国制造”不仅意味着大规模生产，更意味着智能制造，凸显出中国在全球舞台上不断变化的角色。这既是持续的经济改革和技术进步的结果，也体现了精益求精、追求卓越等中国传统价值观。", "pos": "术语", "src": "原文"}, {"term": "new energy vehicle (NEV)", "zh": "新能源汽车", "q": "In 2023, China's production of new energy vehicles reached 20 million units, demonstrating the strength of intelligent manufacturing in China. The Made in China 2025 initiative identifies the NEV indu", "tr": "2023年，中国新能源汽车产量达到2000万辆，彰显了中国智能制造的雄厚实力。《中国制造2025》将新能源汽车产业列为重点突破的战略产业之一。在汽车制造中实现智能化、高度自动化的生产，将有力推动从“中国制造”向中国智能制造的转变。新能源汽车是全球汽车产业转型和绿色发展的主要方向，也是中国推动汽车产业高质量发展的战略选择。", "pos": "术语", "src": "原文"}, {"term": "high-speed rail (HSR)", "zh": "高铁", "q": "China's high-speed rail network, the world's largest, is a testament to the country's engineering prowess and is supported by feats of intelligent manufacturing. A prime example is the Fuxing bullet t", "tr": "中国高铁网络规模居世界第一，是国家工程实力的明证，也得益于智能制造的非凡成就。一个典型例子是“复兴号”动车组，它能够在指定线路上以每小时350公里的时速自动驾驶运行。焊接是列车车体制造中的关键工序。通过对焊接过程进行数字化管理，借助实时数据采集、自动检测和自动报警，可对焊接作业实施持续监控和有效的工艺控制，从而确保更高的焊接质量。", "pos": "术语", "src": "原文"}, {"term": "welding", "zh": "焊接", "q": "China's high-speed rail network, the world's largest, is a testament to the country's engineering prowess and is supported by feats of intelligent manufacturing. A prime example is the Fuxing bullet t", "tr": "中国高铁网络规模居世界第一，是国家工程实力的明证，也得益于智能制造的非凡成就。一个典型例子是“复兴号”动车组，它能够在指定线路上以每小时350公里的时速自动驾驶运行。焊接是列车车体制造中的关键工序。通过对焊接过程进行数字化管理，借助实时数据采集、自动检测和自动报警，可对焊接作业实施持续监控和有效的工艺控制，从而确保更高的焊接质量。", "pos": "术语", "src": "原文"}, {"term": "digital economy", "zh": "数字经济", "q": "Launched by the State Council in 2015, the Made in China 2025 initiative called for accelerating China's transformation from a manufacturing giant (制造大国) into a global manufacturing power (制造强国). Inno", "tr": "2015年，国务院启动《中国制造2025》，提出加快中国从制造大国向制造强国转变。在新兴技术和数字经济的驱动下，传统制造业的创新正在夯实中国智能制造的基础。今天，“中国制造”不仅意味着大规模生产，更意味着智能制造，凸显出中国在全球舞台上不断变化的角色。这既是持续的经济改革和技术进步的结果，也体现了精益求精、追求卓越等中国传统价值观。", "pos": "术语", "src": "原文"}, {"term": "digital infrastructure construction", "zh": "数字基础设施建设", "q": "China has made unprecedented progress in building its digital infrastructure, laying the foundation for technological advancements and economic growth. The country leads the world in both the number o", "tr": "中国在数字基础设施建设方面取得了前所未有的进展，为技术进步和经济增长奠定了基础。中国的5G基站数量和移动数据使用量均居世界首位，网络基础设施规模全球最大、覆盖最广。高速互联网接入广泛普及，背后是庞大的光纤光缆网络作为支撑。", "pos": "术语", "src": "原文"}, {"term": "green development", "zh": "绿色发展", "q": "In 2015, China introduced supply-side structural reform, which focused on optimising the economic structure, reducing inefficiencies, and ensuring long-term sustainability. The reform aimed to enhance", "tr": "2015年，中国提出供给侧结构性改革，着力优化经济结构、减少低效供给、确保长期可持续。改革旨在提高供给体系的质量和效率，进一步释放市场活力、激发社会创造力。中国致力于绿色发展，包括承诺在2060年前实现碳中和，进一步彰显了其对均衡增长、与环境和睦相处的追求。这一理念在中国道家的哲学传统中占据核心地位，道家主张与自然和谐相处。", "pos": "术语", "src": "原文"}, {"term": "“Green Shield” initiative", "zh": "“绿盾”行动", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "术语", "src": "原文"}, {"term": "Two Mountains Theory", "zh": "“两山”理念", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "术语", "src": "原文"}, {"term": "organic farming and agroforestry", "zh": "农林复合经营", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "术语", "src": "原文"}, {"term": "gigawatt", "zh": "千兆瓦", "q": "To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with it", "tr": "为实现2060年前碳中和，中国正转向风能、太阳能、水能等可再生能源。2023年，中国的可再生能源发电装机容量超过500千兆瓦，居全球首位。在“十四五”规划（2021—2025年）中，中国提出到2025年非化石能源占能源消费总量的比重达到20%，这一目标已超额完成。通过对智能电网和特高压直流输电系统的持续投资，中国正在加强能源基础设施、改善能源配置，并更高效地整合可再生能源。", "pos": "术语", "src": "原文"}, {"term": "ultra-high-voltage direct current", "zh": "特高压直流电", "q": "To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with it", "tr": "为实现2060年前碳中和，中国正转向风能、太阳能、水能等可再生能源。2023年，中国的可再生能源发电装机容量超过500千兆瓦，居全球首位。在“十四五”规划（2021—2025年）中，中国提出到2025年非化石能源占能源消费总量的比重达到20%，这一目标已超额完成。通过对智能电网和特高压直流输电系统的持续投资，中国正在加强能源基础设施、改善能源配置，并更高效地整合可再生能源。", "pos": "术语", "src": "原文"}, {"term": "ecological protection and restoration", "zh": "生态保护与修复", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "术语", "src": "原文"}, {"term": "circular economy", "zh": "循环经济", "q": "China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy,", "tr": "中国在绿色技术领域走在前列，在电动汽车、节能电器和可持续建筑材料等方面不断推陈出新。其中的核心是循环经济，它着眼于回收、再利用和减少资源消耗。“十三五”规划（2016—2020年）专门列入循环经济发展规划，以减少废弃物、提高资源利用效率为目标。上海垃圾分类等城市项目有助于减少填埋场使用，并在回收领域创造新的就业岗位。“绿色信贷”政策为采用循环经济做法的行业提供金融支持，而产业共生则鼓励跨行业再利用废弃材料，以增强可持续性。", "pos": "术语", "src": "原文"}, {"term": "Beautiful China Initiative", "zh": "美丽中国", "q": "China's green development strategy is driven by the ambitious \"dual carbon\" goals of reaching peak carbon emissions by 2030 and achieving carbon neutrality by 2060. This initiative accelerates the dev", "tr": "中国的绿色发展战略以“双碳”目标为驱动——力争2030年前实现碳达峰、2060年前实现碳中和，这一目标雄心勃勃。该举措加快了低碳技术的发展，也强化了中国在全球气候治理中的积极作用。中国共产党第二十次全国代表大会强调，尊重自然、保护自然是建设社会主义现代化国家的内在要求。通过推进美丽中国建设，中国力求构建可持续、有韧性的经济，保持人与自然和谐共生，为人民的长远福祉提供保障。", "pos": "术语", "src": "原文"}, {"term": "the Third Plenary Session of the 11th CPC Central Committee", "zh": "中国共产党第十一届中央委员会第三次全体会议", "q": "the Third Plenary Session of the 11th CPC Central Committee: Held in Beijing in December 1978, this key meeting marked the start of China's economic reforms. Led by Deng Xiaoping, it set the focus of ", "tr": "中国共产党第十一届中央委员会第三次全体会议，于1978年12月在北京举行。这次关键会议标志着中国经济改革的开始。在邓小平的领导下，会议将党和国家的工作重点放在经济建设上，开启了从计划经济向市场经济的转型，为中国的现代化进程和改革开放奠定了基础。", "pos": "制度", "src": "原文"}, {"term": "Tianjin Port", "zh": "天津港", "q": "", "tr": "", "pos": "地理", "src": "原文"}, {"term": "China Space Station", "zh": "中国空间站", "q": "China's aerospace intelligent manufacturing has been continuously driving the nation's space industry forward. On 29th April 2021, the Tianhe core module was successfully launched from the Wenchang Sp", "tr": "中国航天智能制造不断推动国家航天事业向前发展。2021年4月29日，天和核心舱在海南文昌航天发射场成功发射，标志着中国空间站在轨组装建造全面展开，也象征着中国正式进入自主建造空间站的新时代。", "pos": "建筑", "src": "原文"}, {"term": "Pudacuo National Park", "zh": "普达措国家公园", "q": "", "tr": "", "pos": "地理", "src": "原文"}, {"term": "Fuzhou Hongmiaoling Waste Incineration Power Plant", "zh": "福州红庙岭垃圾焚烧发电厂", "q": "", "tr": "", "pos": "机构", "src": "原文"}, {"term": "Zhang Qian's Diplomatic Missions to the Western Regions", "zh": "张骞出使西域图", "q": "", "tr": "", "pos": "作品名", "src": "原文"}, {"term": "Stationery Used in China's Signing of WTO Accession Documents", "zh": "中国签署加入世贸组织文件时使用的文具", "q": "", "tr": "", "pos": "其他", "src": "原文"}, {"term": "agriculture", "zh": "农业", "q": "Another example can be seen in agricultural development during the Tang Dynasty, when the rulers recognised the vital importance of agriculture to the nation and its people. In the Hexi Corridor, they", "tr": "另一个例子见于唐朝的农业开发。当时统治者认识到农业对于国家与人民的极端重要性。他们在河西走廊因地制宜，把大片荒漠改造成肥沃的农田。祁连山冰雪融水灌溉使可持续耕作成为可能，让这片土地从一个单纯的通道和军事要塞，演变为富饶的农业和经济区。这种转变体现了道家天人和谐的理念。", "pos": "术语", "src": "原文"}, {"term": "desertification", "zh": "荒漠化", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "术语", "src": "原文"}, {"term": "reforestation", "zh": "再造林", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "术语", "src": "原文"}, {"term": "manufacturing", "zh": "制造业", "q": "During the early period of reform and opening up, China placed strong emphasis on the import of technology as a means of accelerating industrial development. By drawing on foreign expertise, China was", "tr": "改革开放初期，中国高度重视技术引进，将其作为加快工业发展的手段。通过借鉴国外的专长，中国得以迅速实现工业现代化，更有效地参与全球分工。这一战略体现了中国“学习他人”的理念，即在获取知识的同时保持自身文化的独特性。这不仅增强了中国的制造能力，也为中国更深入地融入全球市场、参与国际竞争奠定了基础。", "pos": "术语", "src": "原文"}, {"term": "planned economy", "zh": "计划经济", "q": "the Third Plenary Session of the 11th CPC Central Committee: Held in Beijing in December 1978, this key meeting marked the start of China's economic reforms. Led by Deng Xiaoping, it set the focus of ", "tr": "中国共产党第十一届中央委员会第三次全体会议，于1978年12月在北京举行。这次关键会议标志着中国经济改革的开始。在邓小平的领导下，会议将党和国家的工作重点放在经济建设上，开启了从计划经济向市场经济的转型，为中国的现代化进程和改革开放奠定了基础。", "pos": "术语", "src": "原文"}, {"term": "market economy", "zh": "市场经济", "q": "In 1978, the Third Plenary Session of the 11th CPC Central Committee marked a pivotal moment in China's history, as the country began to embrace reform and opening up. Reform seeks to fundamentally re", "tr": "1978年，党的十一届三中全会成为中国历史上一个关键的时刻，国家由此开始实行改革开放。改革旨在从根本上重塑曾束缚生产力发展的经济体制，建立并完善社会主义市场经济，同时推进政治体制及其他制度领域的相关变革，以确保各方面协调推进；对外开放则着眼对外交往——在经济全球化条件下积极参与国际合作与竞争，扩大同各国的交流，借鉴人类文明的优秀成果，促进中国的发展与现代化。", "pos": "术语", "src": "原文"}, {"term": "special economic zone", "zh": "经济特区", "q": "In 1978, China initiated its historic reform and opening-up policy, which represented a strategic pivot towards unleashing productive forces and prioritising economic development. This transformation ", "tr": "1978年，中国开始实行具有历史意义的改革开放政策，这是一次着力解放生产力、以经济建设为中心的战略转折。这一转变体现了中国在保持社会稳定的同时追求进步的取向。深圳、珠海等城市经济特区的设立，体现了对外开放中务实的态度，其核心在于灵活性与试验性。这些特区通过税收优惠吸引外资，使中国得以在坚守自身传统价值的同时吸收国外先进技术。", "pos": "术语", "src": "原文"}, {"term": "state-owned enterprise", "zh": "国有企业", "q": "A significant focus during this transformative era was the reform of state-owned enterprises, which had long been the backbone of China's economy. The goal was to modernise these enterprises and enhan", "tr": "在这一变革时期，国有企业改革是一个重要的着力点，国有企业长期以来一直是中国经济的支柱。改革目标是使国有企业实现现代化，提升其在全球市场中的竞争力和运营效率。这一时期推行的现代企业制度赋予企业更大的经营自主权，明确了产权，促进了公司治理，为增强责任意识、提高效率奠定了基础。通过改革经营方式、鼓励民间投资，中国力图打造一个富有活力的工业部门，使其能够在日益全球化的世界中蓬勃发展。", "pos": "术语", "src": "原文"}, {"term": "modern enterprise system", "zh": "现代企业制度", "q": "A significant focus during this transformative era was the reform of state-owned enterprises, which had long been the backbone of China's economy. The goal was to modernise these enterprises and enhan", "tr": "在这一变革时期，国有企业改革是一个重要的着力点，国有企业长期以来一直是中国经济的支柱。改革目标是使国有企业实现现代化，提升其在全球市场中的竞争力和运营效率。这一时期推行的现代企业制度赋予企业更大的经营自主权，明确了产权，促进了公司治理，为增强责任意识、提高效率奠定了基础。通过改革经营方式、鼓励民间投资，中国力图打造一个富有活力的工业部门，使其能够在日益全球化的世界中蓬勃发展。", "pos": "制度", "src": "原文"}, {"term": "supply-side structural reform", "zh": "供给侧结构性改革", "q": "In 2015, China introduced supply-side structural reform, which focused on optimising the economic structure, reducing inefficiencies, and ensuring long-term sustainability. The reform aimed to enhance", "tr": "2015年，中国提出供给侧结构性改革，着力优化经济结构、减少低效供给、确保长期可持续。改革旨在提高供给体系的质量和效率，进一步释放市场活力、激发社会创造力。中国致力于绿色发展，包括承诺在2060年前实现碳中和，进一步彰显了其对均衡增长、与环境和睦相处的追求。这一理念在中国道家的哲学传统中占据核心地位，道家主张与自然和谐相处。", "pos": "制度", "src": "原文"}, {"term": "Made in China 2025", "zh": "中国制造2025", "q": "Launched by the State Council in 2015, the Made in China 2025 initiative called for accelerating China's transformation from a manufacturing giant (制造大国) into a global manufacturing power (制造强国). Inno", "tr": "2015年，国务院启动《中国制造2025》，提出加快中国从制造大国向制造强国转变。在新兴技术和数字经济的驱动下，传统制造业的创新正在夯实中国智能制造的基础。今天，“中国制造”不仅意味着大规模生产，更意味着智能制造，凸显出中国在全球舞台上不断变化的角色。这既是持续的经济改革和技术进步的结果，也体现了精益求精、追求卓越等中国传统价值观。", "pos": "其他", "src": "原文"}, {"term": "carbon peaking", "zh": "碳达峰", "q": "China's green development strategy is driven by the ambitious \"dual carbon\" goals of reaching peak carbon emissions by 2030 and achieving carbon neutrality by 2060. This initiative accelerates the dev", "tr": "中国的绿色发展战略以“双碳”目标为驱动——力争2030年前实现碳达峰、2060年前实现碳中和，这一目标雄心勃勃。该举措加快了低碳技术的发展，也强化了中国在全球气候治理中的积极作用。中国共产党第二十次全国代表大会强调，尊重自然、保护自然是建设社会主义现代化国家的内在要求。通过推进美丽中国建设，中国力求构建可持续、有韧性的经济，保持人与自然和谐共生，为人民的长远福祉提供保障。", "pos": "术语", "src": "原文"}, {"term": "carbon neutrality", "zh": "碳中和", "q": "In 2015, China introduced supply-side structural reform, which focused on optimising the economic structure, reducing inefficiencies, and ensuring long-term sustainability. The reform aimed to enhance", "tr": "2015年，中国提出供给侧结构性改革，着力优化经济结构、减少低效供给、确保长期可持续。改革旨在提高供给体系的质量和效率，进一步释放市场活力、激发社会创造力。中国致力于绿色发展，包括承诺在2060年前实现碳中和，进一步彰显了其对均衡增长、与环境和睦相处的追求。这一理念在中国道家的哲学传统中占据核心地位，道家主张与自然和谐相处。", "pos": "术语", "src": "原文"}, {"term": "“dual carbon” goals", "zh": "双碳目标", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "high-quality development", "zh": "高质量发展", "q": "By 2012, China had entered a new phase of development, prioritising high-quality development and sustainable development. The shift towards a more balanced approach to economic development reflected C", "tr": "到2012年，中国进入新的发展阶段，着力推动高质量发展和可持续发展。向更加均衡的经济发展方式转变，体现了中国文化对和谐与可持续的追求——这些理念在中国古代哲学中有着深厚的根基。2013年提出的“一带一路”倡议正是这一精神的体现：它促进国际合作与贸易，同时强化中国对互利共赢和全球伙伴关系的承诺，这一理念与中国传统的相互依存观念一脉相承。", "pos": "术语", "src": "原文"}, {"term": "sustainable development", "zh": "可持续发展", "q": "By 2012, China had entered a new phase of development, prioritising high-quality development and sustainable development. The shift towards a more balanced approach to economic development reflected C", "tr": "到2012年，中国进入新的发展阶段，着力推动高质量发展和可持续发展。向更加均衡的经济发展方式转变，体现了中国文化对和谐与可持续的追求——这些理念在中国古代哲学中有着深厚的根基。2013年提出的“一带一路”倡议正是这一精神的体现：它促进国际合作与贸易，同时强化中国对互利共赢和全球伙伴关系的承诺，这一理念与中国传统的相互依存观念一脉相承。", "pos": "术语", "src": "原文"}, {"term": "socialism with Chinese characteristics", "zh": "中国特色社会主义", "q": "The reform and opening-up policy has not only transformed China's economy but also reshaped its social and cultural landscape. It encouraged open-mindedness and innovation, embraced diverse perspectiv", "tr": "改革开放政策不仅改变了中国的经济，也重塑了其社会与文化面貌。它鼓励开放包容与创新，吸纳多元视角，把现代化融入中国特色社会主义。在文化上，这一时期培育出更加生机勃勃的局面：中国的电影、音乐、文学和传媒产业随着科学技术的迅猛进步而蓬勃发展。教育改革进一步壮大了国家的劳动力队伍，使其做好准备，在日益全球化的世界中大展身手，同时坚守集体进步与社会和谐的核心价值。", "pos": "术语", "src": "原文"}, {"term": "5G base station", "zh": "5G基站", "q": "China has made unprecedented progress in building its digital infrastructure, laying the foundation for technological advancements and economic growth. The country leads the world in both the number o", "tr": "中国在数字基础设施建设方面取得了前所未有的进展，为技术进步和经济增长奠定了基础。中国的5G基站数量和移动数据使用量均居世界首位，网络基础设施规模全球最大、覆盖最广。高速互联网接入广泛普及，背后是庞大的光纤光缆网络作为支撑。", "pos": "术语", "src": "原文"}, {"term": "e-commerce", "zh": "电子商务", "q": "China's digital economy has evolved through three distinct stages. The first, from 1994 to 2004, was the incubation stage, when the commercial internet began to take shape, and a number of domestic in", "tr": "中国数字经济经历了三个不同阶段。第一阶段是1994年至2004年的萌芽期，此时商业互联网初具雏形，一批本土互联网企业相继涌现，为中国数字经济格局奠定了基础。第二阶段是2005年至2015年，以电子商务、网络银行、门户网站和游戏产业驱动的爆发式增长为标志，推动数字经济进入快速扩张期。自2016年起，中国进入融合协同阶段，其特点是数字技术与实体经济在国内深度融合，同时积极参与全球数字经济治理。", "pos": "术语", "src": "原文"}, {"term": "sharing economy", "zh": "共享经济", "q": "The digital economy has transformed various sectors, creating new opportunities and changing the way businesses operate and people interact. Key drivers of this shift include e-commerce, the sharing e", "tr": "数字经济改变了诸多行业，创造了新的机遇，也改变了企业的经营方式和人们的交往方式。推动这一转变的主要动力包括电子商务、共享经济和移动支付。", "pos": "术语", "src": "原文"}, {"term": "mobile payment", "zh": "移动支付", "q": "3 Which mobile payment app do you use most often, and when do you usually use it?", "tr": "3 你最常使用哪款移动支付应用？通常在什么时候使用？", "pos": "术语", "src": "原文"}, {"term": "smart city", "zh": "智慧城市", "q": "China's digital infrastructure also involves intelligent transportation systems and the development of smart cities, which have significantly improved efficiency in urban mobility and the delivery of ", "tr": "中国的数字基础设施还包括智能交通系统和智慧城市建设，它们显著提高了城市出行效率和公共服务的供给效率。政府对智慧城镇化的重视，与建设和谐宜居城市的目标相契合——在这一目标下，技术进步不仅要促进经济增长，还要增进社会福祉。", "pos": "术语", "src": "原文"}, {"term": "renewable energy", "zh": "可再生能源", "q": "To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with it", "tr": "为实现2060年前碳中和，中国正转向风能、太阳能、水能等可再生能源。2023年，中国的可再生能源发电装机容量超过500千兆瓦，居全球首位。在“十四五”规划（2021—2025年）中，中国提出到2025年非化石能源占能源消费总量的比重达到20%，这一目标已超额完成。通过对智能电网和特高压直流输电系统的持续投资，中国正在加强能源基础设施、改善能源配置，并更高效地整合可再生能源。", "pos": "术语", "src": "原文"}, {"term": "non-fossil energy", "zh": "非化石能源", "q": "To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with it", "tr": "为实现2060年前碳中和，中国正转向风能、太阳能、水能等可再生能源。2023年，中国的可再生能源发电装机容量超过500千兆瓦，居全球首位。在“十四五”规划（2021—2025年）中，中国提出到2025年非化石能源占能源消费总量的比重达到20%，这一目标已超额完成。通过对智能电网和特高压直流输电系统的持续投资，中国正在加强能源基础设施、改善能源配置，并更高效地整合可再生能源。", "pos": "术语", "src": "原文"}, {"term": "smart grid", "zh": "智能电网", "q": "To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with it", "tr": "为实现2060年前碳中和，中国正转向风能、太阳能、水能等可再生能源。2023年，中国的可再生能源发电装机容量超过500千兆瓦，居全球首位。在“十四五”规划（2021—2025年）中，中国提出到2025年非化石能源占能源消费总量的比重达到20%，这一目标已超额完成。通过对智能电网和特高压直流输电系统的持续投资，中国正在加强能源基础设施、改善能源配置，并更高效地整合可再生能源。", "pos": "术语", "src": "原文"}, {"term": "14th Five-Year Plan", "zh": "十四五规划", "q": "To achieve carbon neutrality by 2060, China is transitioning to renewable energy sources like wind, solar, and hydropower. In 2023, China took the lead globally in renewable energy production, with it", "tr": "为实现2060年前碳中和，中国正转向风能、太阳能、水能等可再生能源。2023年，中国的可再生能源发电装机容量超过500千兆瓦，居全球首位。在“十四五”规划（2021—2025年）中，中国提出到2025年非化石能源占能源消费总量的比重达到20%，这一目标已超额完成。通过对智能电网和特高压直流输电系统的持续投资，中国正在加强能源基础设施、改善能源配置，并更高效地整合可再生能源。", "pos": "制度", "src": "原文"}, {"term": "13th Five-Year Plan", "zh": "十三五规划", "q": "China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy,", "tr": "中国在绿色技术领域走在前列，在电动汽车、节能电器和可持续建筑材料等方面不断推陈出新。其中的核心是循环经济，它着眼于回收、再利用和减少资源消耗。“十三五”规划（2016—2020年）专门列入循环经济发展规划，以减少废弃物、提高资源利用效率为目标。上海垃圾分类等城市项目有助于减少填埋场使用，并在回收领域创造新的就业岗位。“绿色信贷”政策为采用循环经济做法的行业提供金融支持，而产业共生则鼓励跨行业再利用废弃材料，以增强可持续性。", "pos": "制度", "src": "原文"}, {"term": "green credit", "zh": "绿色信贷", "q": "China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy,", "tr": "中国在绿色技术领域走在前列，在电动汽车、节能电器和可持续建筑材料等方面不断推陈出新。其中的核心是循环经济，它着眼于回收、再利用和减少资源消耗。“十三五”规划（2016—2020年）专门列入循环经济发展规划，以减少废弃物、提高资源利用效率为目标。上海垃圾分类等城市项目有助于减少填埋场使用，并在回收领域创造新的就业岗位。“绿色信贷”政策为采用循环经济做法的行业提供金融支持，而产业共生则鼓励跨行业再利用废弃材料，以增强可持续性。", "pos": "术语", "src": "原文"}, {"term": "industrial symbiosis", "zh": "工业共生", "q": "China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy,", "tr": "中国在绿色技术领域走在前列，在电动汽车、节能电器和可持续建筑材料等方面不断推陈出新。其中的核心是循环经济，它着眼于回收、再利用和减少资源消耗。“十三五”规划（2016—2020年）专门列入循环经济发展规划，以减少废弃物、提高资源利用效率为目标。上海垃圾分类等城市项目有助于减少填埋场使用，并在回收领域创造新的就业岗位。“绿色信贷”政策为采用循环经济做法的行业提供金融支持，而产业共生则鼓励跨行业再利用废弃材料，以增强可持续性。", "pos": "术语", "src": "原文"}, {"term": "ecological civilisation", "zh": "生态文明", "q": "The concept of \"harmony between humanity and nature\" is a defining feature of Chinese civilisation. Respect for nature and dedication to protecting it have ensured the survival and prosperity of the C", "tr": "“天人合一”的理念是中华文明的一个鲜明特征。敬畏自然、致力于保护自然，使中华民族得以生生不息、繁荣发展数千年。为推进生态文明建设，改革开放之初，中国就把节约资源和保护环境确立为基本国策，把可持续发展确立为国家战略。", "pos": "术语", "src": "原文"}, {"term": "National Park System", "zh": "国家公园体系", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "制度", "src": "原文"}, {"term": "shared prosperity", "zh": "共同富裕", "q": "E-commerce in China has revolutionised retail, driven by the rapidly growing consumer base and widespread internet access. Some platforms have become integral to daily life, expanding product availabi", "tr": "在迅速壮大的消费群体和广泛普及的互联网的推动下，中国的电子商务彻底改变了零售业。一些平台已成为日常生活不可或缺的一部分，既丰富了商品的可得性，又使企业能够触达全国各地的消费者。这种转变注重实用性，因为技术被用来解决现实生活中实实在在的需求。此外，电子商务显著缩小了城乡差距，让农民和本地生产者能够直接对接更广阔的市场，从而增加收入、促进区域发展。因此，电子商务不仅是一场商业革命，更已成为包容性增长和区域均衡发展的推动力，体现了中国共同富裕的更宏大愿景。", "pos": "术语", "src": "原文"}, {"term": "power battery", "zh": "动力电池", "q": "Power batteries are the core component of NEVs, and China's power-battery sector has achieved continuous breakthroughs in materials and new-technology applications. On the technological front, China h", "tr": "动力电池是新能源汽车的核心部件，中国动力电池产业在材料和新一代技术应用方面不断取得突破。在技术层面，近年来中国还在多项新能源汽车相关技术上取得突破，显著提升了整车的智能化水平。", "pos": "术语", "src": "原文"}, {"term": "electric vehicle", "zh": "电动汽车", "q": "China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy,", "tr": "中国在绿色技术领域走在前列，在电动汽车、节能电器和可持续建筑材料等方面不断推陈出新。其中的核心是循环经济，它着眼于回收、再利用和减少资源消耗。“十三五”规划（2016—2020年）专门列入循环经济发展规划，以减少废弃物、提高资源利用效率为目标。上海垃圾分类等城市项目有助于减少填埋场使用，并在回收领域创造新的就业岗位。“绿色信贷”政策为采用循环经济做法的行业提供金融支持，而产业共生则鼓励跨行业再利用废弃材料，以增强可持续性。", "pos": "术语", "src": "原文"}, {"term": "waste sorting", "zh": "垃圾分类", "q": "China has taken a leading role in green technology, with innovations in electric vehicles, energy-efficient appliances, and sustainable construction materials. Central to this is the circular economy,", "tr": "中国在绿色技术领域走在前列，在电动汽车、节能电器和可持续建筑材料等方面不断推陈出新。其中的核心是循环经济，它着眼于回收、再利用和减少资源消耗。“十三五”规划（2016—2020年）专门列入循环经济发展规划，以减少废弃物、提高资源利用效率为目标。上海垃圾分类等城市项目有助于减少填埋场使用，并在回收领域创造新的就业岗位。“绿色信贷”政策为采用循环经济做法的行业提供金融支持，而产业共生则鼓励跨行业再利用废弃材料，以增强可持续性。", "pos": "术语", "src": "原文"}, {"term": "filial piety", "zh": "孝", "q": "In traditional family-run businesses, long-term stability and moral leadership were regarded as essential. Success was seen not merely as personal achievement but as a responsibility to both the famil", "tr": "在传统的家族企业中，长期稳定与道德引领被视为至关重要的要素。成功不仅被看作个人的成就，更被看作对家庭和社会应尽的责任。孝、德行等儒家价值观，加上对教育的高度重视，被认为是维系家业兴旺、以对社会负责的方式取得商业成功的关键。", "pos": "术语", "src": "原文"}, {"term": "Qin Dynasty", "zh": "秦朝", "q": "The Qin Dynasty, under the rule of Emperor Qin Shihuang, is the most prominent example of Legalist governance in practice. Centralised authority and legal reforms, such as the standardisation of curre", "tr": "秦始皇统治下的秦朝，是法家治国理念付诸实践最突出的范例。中央集权与法律改革，如统一货币、统一度量衡，有助于统一帝国，便利了远距离贸易，推动了经济整合。修路、开渠、筑长城等基础设施工程同样体现了法家理想。这些举措不仅是为了支持商业，也是为了巩固国家控制、掌控资源、维系帝国各地的秩序。这种对行政统一和中央集权的重视，为经济增长和统一六国奠定了基础。", "pos": "朝代", "src": "原文"}, {"term": "Han Dynasty", "zh": "汉朝", "q": "The intersection of economic philosophy and historical commercial activity is most evident in China's trade networks, particularly along the Silk Road. Established during the Han Dynasty, the ancient ", "tr": "经济哲学与历史商业活动的交汇，在中国的贸易网络，尤其是丝绸之路沿线，体现得最为明显。古老的丝绸之路始建于汉代，是一个连接中国与亚洲、欧洲和非洲各地的庞大贸易路线网络。汉唐时期，中国经历了前所未有的社会与经济繁荣。这种显著的繁荣使中国成为丝绸之路发展的主导力量，也体现了儒家关于社会责任的理想。历代中国政府也在丝绸之路的发展中发挥了不可或缺的作用。它们通过设置官职、制定法律政策、加强制度治理，为贸易提供了规制基础——这正是法家厉行法治、强化治理主张的实际体现。", "pos": "朝代", "src": "原文"}, {"term": "Tang Dynasty", "zh": "唐朝", "q": "Daoist ideas have also influenced urban planning. For example, the central area of Xi'an during the Tang Dynasty was designed based on the principles of balance and harmony. The layout aimed to harmon", "tr": "道家思想也影响了城市规划。例如，唐朝西安的城市中心区便是依据平衡与和谐的原则设计的。其布局力求使人类活动与自然相协调，体现了道家的信念：经济繁荣与城市发展应当尊重自然、与自然环境保持平衡。", "pos": "朝代", "src": "原文"}, {"term": "Qing Dynasty", "zh": "清朝", "q": "The piaohao (票号), or draft banks, of the Qing Dynasty, are a prime example of this concept. Established by merchants from Shanxi, these institutions were based on mutual trust and responsibility, alig", "tr": "清朝的票号便是这一理念的典型范例。票号由山西商人创办，以相互信任与责任为基础，契合儒家关于诚信与社会福祉的理想。经营票号的商人不仅取得了商业上的成功，还回馈乡里，展现出经济活动如何促进社会和谐。", "pos": "朝代", "src": "原文"}, {"term": "Hexi Corridor", "zh": "河西走廊", "q": "Another example can be seen in agricultural development during the Tang Dynasty, when the rulers recognised the vital importance of agriculture to the nation and its people. In the Hexi Corridor, they", "tr": "另一个例子见于唐朝的农业开发。当时统治者认识到农业对于国家与人民的极端重要性。他们在河西走廊因地制宜，把大片荒漠改造成肥沃的农田。祁连山冰雪融水灌溉使可持续耕作成为可能，让这片土地从一个单纯的通道和军事要塞，演变为富饶的农业和经济区。这种转变体现了道家天人和谐的理念。", "pos": "地理", "src": "原文"}, {"term": "Qilian Mountains", "zh": "祁连山", "q": "Another example can be seen in agricultural development during the Tang Dynasty, when the rulers recognised the vital importance of agriculture to the nation and its people. In the Hexi Corridor, they", "tr": "另一个例子见于唐朝的农业开发。当时统治者认识到农业对于国家与人民的极端重要性。他们在河西走廊因地制宜，把大片荒漠改造成肥沃的农田。祁连山冰雪融水灌溉使可持续耕作成为可能，让这片土地从一个单纯的通道和军事要塞，演变为富饶的农业和经济区。这种转变体现了道家天人和谐的理念。", "pos": "地理", "src": "原文"}, {"term": "Loess Plateau", "zh": "黄土高原", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "地理", "src": "原文"}, {"term": "Taihang Mountains", "zh": "太行山", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "地理", "src": "原文"}, {"term": "Fuxing (bullet train)", "zh": "复兴号", "q": "China's high-speed rail network, the world's largest, is a testament to the country's engineering prowess and is supported by feats of intelligent manufacturing. A prime example is the Fuxing bullet t", "tr": "中国高铁网络规模居世界第一，是国家工程实力的明证，也得益于智能制造的非凡成就。一个典型例子是“复兴号”动车组，它能够在指定线路上以每小时350公里的时速自动驾驶运行。焊接是列车车体制造中的关键工序。通过对焊接过程进行数字化管理，借助实时数据采集、自动检测和自动报警，可对焊接作业实施持续监控和有效的工艺控制，从而确保更高的焊接质量。", "pos": "其他", "src": "原文"}, {"term": "Tianhe Core Module", "zh": "天和核心舱", "q": "China's aerospace intelligent manufacturing has been continuously driving the nation's space industry forward. On 29th April 2021, the Tianhe core module was successfully launched from the Wenchang Sp", "tr": "中国航天智能制造不断推动国家航天事业向前发展。2021年4月29日，天和核心舱在海南文昌航天发射场成功发射，标志着中国空间站在轨组装建造全面展开，也象征着中国正式进入自主建造空间站的新时代。", "pos": "建筑", "src": "原文"}, {"term": "Wenchang Space Launch Site", "zh": "文昌航天发射场", "q": "China's aerospace intelligent manufacturing has been continuously driving the nation's space industry forward. On 29th April 2021, the Tianhe core module was successfully launched from the Wenchang Sp", "tr": "中国航天智能制造不断推动国家航天事业向前发展。2021年4月29日，天和核心舱在海南文昌航天发射场成功发射，标志着中国空间站在轨组装建造全面展开，也象征着中国正式进入自主建造空间站的新时代。", "pos": "机构", "src": "原文"}, {"term": "State Council", "zh": "国务院", "q": "Launched by the State Council in 2015, the Made in China 2025 initiative called for accelerating China's transformation from a manufacturing giant (制造大国) into a global manufacturing power (制造强国). Inno", "tr": "2015年，国务院启动《中国制造2025》，提出加快中国从制造大国向制造强国转变。在新兴技术和数字经济的驱动下，传统制造业的创新正在夯实中国智能制造的基础。今天，“中国制造”不仅意味着大规模生产，更意味着智能制造，凸显出中国在全球舞台上不断变化的角色。这既是持续的经济改革和技术进步的结果，也体现了精益求精、追求卓越等中国传统价值观。", "pos": "机构", "src": "原文"}, {"term": "Communist Party of China", "zh": "中国共产党", "q": "This period was marked by the establishment of a socialist market economy, following the 14th National Congress of the Communist Party of China in 1992. The government decided to accelerate the pace o", "tr": "1992年中国共产党第十四次全国代表大会之后，社会主义市场经济的建立成为这一时期的标志。政府决定加快改革开放步伐，力求在资源配置中兼顾效率与公平。这一转变不仅增强了经济实力，也提高了中国人民的生活水平。随着经济机会不断扩大、为个人和国家走向富裕开辟出新的道路，民众心中日益充满希望与抱负。这一转变汲取了中华文化中自强不息这一历久弥新的价值，促进了集体与个人的共同进步。", "pos": "机构", "src": "原文"}, {"term": "14th National Congress of the Communist Party of China", "zh": "中国共产党第十四次全国代表大会", "q": "This period was marked by the establishment of a socialist market economy, following the 14th National Congress of the Communist Party of China in 1992. The government decided to accelerate the pace o", "tr": "1992年中国共产党第十四次全国代表大会之后，社会主义市场经济的建立成为这一时期的标志。政府决定加快改革开放步伐，力求在资源配置中兼顾效率与公平。这一转变不仅增强了经济实力，也提高了中国人民的生活水平。随着经济机会不断扩大、为个人和国家走向富裕开辟出新的道路，民众心中日益充满希望与抱负。这一转变汲取了中华文化中自强不息这一历久弥新的价值，促进了集体与个人的共同进步。", "pos": "事件", "src": "原文"}, {"term": "18th National Congress of the Communist Party of China", "zh": "中国共产党第十八次全国代表大会", "q": "the Beautiful China Initiative: The concept of Beautiful China was put forward at the 18th National Congress of the Communist Party of China. It emphasises placing ecological civilisation building in ", "tr": "“美丽中国”是中国共产党第十八次全国代表大会提出的概念，强调把生态文明建设放在突出地位，融入经济建设、政治建设、文化建设、社会建设各方面和全过程。美丽中国建设评估指标体系包括空气清新、水体洁净、土壤安全、生态良好、人居整洁五类指标。", "pos": "事件", "src": "原文"}, {"term": "20th CPC National Congress", "zh": "中国共产党第二十次全国代表大会", "q": "China's green development strategy is driven by the ambitious \"dual carbon\" goals of reaching peak carbon emissions by 2030 and achieving carbon neutrality by 2060. This initiative accelerates the dev", "tr": "中国的绿色发展战略以“双碳”目标为驱动——力争2030年前实现碳达峰、2060年前实现碳中和，这一目标雄心勃勃。该举措加快了低碳技术的发展，也强化了中国在全球气候治理中的积极作用。中国共产党第二十次全国代表大会强调，尊重自然、保护自然是建设社会主义现代化国家的内在要求。通过推进美丽中国建设，中国力求构建可持续、有韧性的经济，保持人与自然和谐共生，为人民的长远福祉提供保障。", "pos": "事件", "src": "原文"}, {"term": "China's high-speed rail", "zh": "中国高铁", "q": "China's high-speed rail network, the world's largest, is a testament to the country's engineering prowess and is supported by feats of intelligent manufacturing. A prime example is the Fuxing bullet t", "tr": "中国高铁网络规模居世界第一，是国家工程实力的明证，也得益于智能制造的非凡成就。一个典型例子是“复兴号”动车组，它能够在指定线路上以每小时350公里的时速自动驾驶运行。焊接是列车车体制造中的关键工序。通过对焊接过程进行数字化管理，借助实时数据采集、自动检测和自动报警，可对焊接作业实施持续监控和有效的工艺控制，从而确保更高的焊接质量。", "pos": "术语", "src": "原文"}, {"term": "lucid waters and lush mountains are invaluable assets", "zh": "绿水青山就是金山银山", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "术语", "src": "原文"}, {"term": "ecotourism", "zh": "生态旅游", "q": "China has made ecological protection and restoration a central component of its green development strategy. One key initiative is the establishment of the National Park System, which conserves biodive", "tr": "中国把生态保护与修复作为绿色发展战略的核心内容。一项重要举措是建立国家公园体制，在张家界、普达措等国家公园保护生物多样性、促进生态旅游。“绿盾”行动着力加强黄土高原、太行山等地的植树造林，逆转土地荒漠化，改善土壤质量。此外，习近平主席的“两山”理念强调“绿水青山就是金山银山”。这一理念鼓励通过有机农业、农林复合经营等做法，在经济增长与环境保护之间实现平衡。", "pos": "术语", "src": "原文"}, {"term": "green agriculture", "zh": "绿色农业", "q": "", "tr": "", "pos": "术语", "src": "原文"}], "vocabB": [], "examsA": [{"term": "", "zh": "", "cn": "近年来，中国政府高度重视民营经济（private economy）的发展，出台了一系列政策支持民营企业。", "en": "In recent years, the Chinese government has attached great importance to the development of the private economy and issued a series of policies to support private enterprises.", "ptype": "真题", "cat": "真题A", "map": "民营经济", "set": "CET4 2025·12·S1", "src": "CET4 2025·12·S1", "cls": "Chapter 11", "tip": "断句:分句①\"中国政府高度重视…的发展\"/②\"出台了一系列政策支持民营企业\";核心=①;②→并列谓语(and issued…)/目的状语;时锚:近年来→现在完成时;话题:补主语(→The Chinese government);文化:民营经济→S1 private economy(原卷括注 private economy，同源优先/教材库)；民营企业→S1 private enterprises(库)", "ta": "补主语；时间状语前置（In recent years，连淑能 1993）；时态呼应（现在完成时，连淑能 1993）；目的状语（to support…）。", "te": "惯用等值（\"高度重视\"→attach great importance to）；词性转换（\"出台\"→issued）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"民营经济\"从原卷括注 private economy（同源优先），库内定译见 scio/gov/China Daily（S1）；\"民营企业\"见 gov/CGTN（private enterprises，S1）；\"高度重视…的发展\"见 scio（attach great importance to the development of，S1）。", "rp": "`attach great importance to the development of`（L2·PC，库）；`a series of`（L2·PC）；`issue policies to V`（L2·PC）。"}, {"term": "", "zh": "", "cn": "截至 2025 年 3 月底，全国民营企业数量超过 5700 万家，占企业总量的 92.3%。", "en": "By the end of March 2025, the number of private enterprises nationwide had exceeded 57 million, accounting for 92.3 percent of all enterprises.", "ptype": "真题", "cat": "真题A", "map": "民营经济", "set": "CET4 2025·12·S1", "src": "CET4 2025·12·S1", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→伴随状语(分词 accounting for…);话题:补主语(→the number of private enterprises nationwide);时锚:截至…→过去完成时;文化:民营企业→private enterprises(库)；占…%→accounting for … percent(库)", "ta": "补主语；时间状语前置（By the end of…，连淑能 1993）；分词状语（accounting for…，连淑能 1993）；时态呼应（过去完成时）。", "te": "数字转换（\"5700 万家\"→57 million）；词性转换（\"超过\"→had exceeded）；惯用等值（\"占…\"→accounting for）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"民营企业\"见 gov/CGTN（private enterprises，S1）；\"占…%\"见 gov（accounting for … percent，S1）。", "rp": "`account for … percent`（L2·PC，库）；`by the end of`（L2·PC）；`V-ing 状语`（L2·SB）→ 本句实例：…, accounting for 92.3 percent of all enterprises。"}, {"term": "", "zh": "", "cn": "民营企业不仅数量稳步增长，质量和结构也在不断提升。", "en": "Private enterprises have not only grown steadily in number but also kept improving in quality and structure.", "ptype": "真题", "cat": "真题A", "map": "民营经济", "set": "CET4 2025·12·S1", "src": "CET4 2025·12·S1", "cls": "Chapter 11", "tip": "断句:分句①②;核心=并列;触发[不仅…也…]→not only … but also …;话题:补主语(→Private enterprises);逻辑:递进→not only … but also …;文化:民营企业→private enterprises(库)", "ta": "补主语；意合→形合（递进 not only … but also …，连淑能 1993）。", "te": "动词转译（\"增长\"→grown；\"提升\"→improving）；增补（steadily）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"民营企业\"见 gov/CGTN（private enterprises，S1）。", "rp": "`not only … but also …`（L2·SB）→ 本句实例：have not only grown steadily in number but also kept improving in quality and structure；`grow steadily`（L2·PC）。"}, {"term": "", "zh": "", "cn": "民营企业的研发投入不断增加，在新一代信息技术、人工智能等领域发展迅速。", "en": "Private enterprises have kept increasing their R&D investment and are developing rapidly in fields such as new-generation information technology and artificial intelligence.", "ptype": "真题", "cat": "真题A", "map": "民营经济", "set": "CET4 2025·12·S1", "src": "CET4 2025·12·S1", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→并列谓语(and are developing rapidly…);话题:补主语(→Private enterprises);时锚:不断增加→现在完成时|现在进行时;文化:研发投入→R&D investment；新一代信息技术→S1 new-generation information technology(库)；人工智能→S1 artificial intelligence(库)", "ta": "补主语；意合→形合（并列谓语，连淑能 1993）；时态呼应（现在完成时/现在进行时）。", "te": "增补（such as）；词性转换（\"研发投入\"→R&D investment）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"新一代信息技术、人工智能\"见 China Daily Asia（new-generation information technology, artificial intelligence，S1）。", "rp": "`R&D investment`（L2·PC）；`fields such as …`（L2·PC）；`develop rapidly in`（L2·PC）。"}, {"term": "", "zh": "", "cn": "民营企业核心竞争力的增强为中国经济的高质量发展提供了有力支撑。", "en": "The enhancement of the core competitiveness of private enterprises has provided strong support for the high-quality development of the Chinese economy.", "ptype": "真题", "cat": "真题A", "map": "民营经济", "set": "CET4 2025·12·S1", "src": "CET4 2025·12·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:名词化主语(\"…的增强\"→The enhancement of…);文化:核心竞争力→S1 core competitiveness(库)；高质量发展→S1 high-quality development(库/教材)；民营企业→private enterprises(库)", "ta": "名词化主语（\"…的增强\"→The enhancement of…，连淑能 1993）；补主语；修饰语后置（of 短语）。", "te": "名词化（\"增强\"→enhancement）；增补（strong）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"核心竞争力\"见 gov（core competitiveness，S1）；\"高质量发展\"官方定译见 新华/scio/gov（high-quality development，S1）。", "rp": "`provide strong support for`（L2·PC）；`core competitiveness`（L2·PC）；`high-quality development`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国是世界上最古老的文明之一。", "en": "China is one of the oldest civilizations in the world.", "ptype": "真题", "cat": "真题A", "map": "中国经济发展（工业革命·出口·第二大经济体）", "set": "CET4 2015·06·S1", "src": "CET4 2015·06·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→China);文化:文明→civilization", "ta": "补主语（话题→主语，Li & Thompson 1976）；修饰语后置（in the world）。", "te": "增补（the）；惯用等值（\"最古老的…之一\"→one of the oldest…）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`one of the oldest … in the world`（L2·PC）。"}, {"term": "", "zh": "", "cn": "构成现代世界基础的许多元素都起源于中国。", "en": "Many elements that form the basis of the modern world originated in China.", "ptype": "真题", "cat": "真题A", "map": "中国经济发展（工业革命·出口·第二大经济体）", "set": "CET4 2015·06·S1", "src": "CET4 2015·06·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→Many elements);受事定语前置→后置定语(that form the basis of…);文化:起源→originate in", "ta": "补主语；定语从句后置（\"构成现代世界基础的\"→that form the basis of…，连淑能 1993）。", "te": "词性转换（\"起源\"→originated in）；增补（the）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`form the basis of`（L2·PC）；`originate in`（L2·PC）；`N + that + V …`（定语从句，L2·SB）→ 本句实例：Many elements that form the basis of the modern world originated in China。"}, {"term": "", "zh": "", "cn": "中国现在拥有世界上发展最快的经济，并正经历着一次新的工业革命。", "en": "China now has the fastest-growing economy in the world and is undergoing a new industrial revolution.", "ptype": "真题", "cat": "真题A", "map": "中国经济发展（工业革命·出口·第二大经济体）", "set": "CET4 2015·06·S1", "src": "CET4 2015·06·S1", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→并列谓语(and is undergoing…);时锚:现在→一般现在/现在进行时;话题:补主语(→China);文化:工业革命→industrial revolution", "ta": "补主语；意合→形合（并列谓语 and）；时态呼应（现在进行时）。", "te": "词性转换（\"拥有\"→has；\"经历\"→is undergoing）；增补（now）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`the fastest-growing economy`（L2·PC）；`undergo a … revolution`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国还启动了雄心勃勃的太空探索计划，其中包括到2020年建成一个太空站。", "en": "China has also launched an ambitious space exploration program, which includes building a space station by 2020.", "ptype": "真题", "cat": "真题A", "map": "中国经济发展（工业革命·出口·第二大经济体）", "set": "CET4 2015·06·S1", "src": "CET4 2015·06·S1", "cls": "Chapter 11", "tip": "断句:分句①\"启动了…计划\"/②\"其中包括…\";核心=①;②→非限制性定语从句(which includes…);时锚:启动了→一般过去时;话题:补主语(→China);文化:太空探索→space exploration；太空站→space station", "ta": "补主语；定语从句后置（which includes…，连淑能 1993）。", "te": "动词转动名词（\"建成\"→building）；增补（also）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`space exploration program`（L2·PC）；`an ambitious plan/program`（L2·PC）；`, which + V …`（非限定从，L2·SB）→ 本句实例：…, which includes building a space station by 2020。"}, {"term": "", "zh": "", "cn": "目前,中国是世界最大的出口国之一，并正在吸引大量外国投资。", "en": "At present, China is one of the world's largest exporters and is attracting a large amount of foreign investment.", "ptype": "真题", "cat": "真题A", "map": "中国经济发展（工业革命·出口·第二大经济体）", "set": "CET4 2015·06·S1", "src": "CET4 2015·06·S1", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→并列谓语(and is attracting…);时锚:目前→一般现在/现在进行时;话题:补主语(→China);文化:出口国→exporter；外国投资→foreign investment；备注:[原卷如此]（\"目前,\"为半角逗号，照抄不改）", "ta": "补主语；时间状语前置（At present，连淑能 1993）；意合→形合（并列谓语）；时态呼应（现在进行时）。", "te": "增补（a large amount of）；词性转换（\"出口国\"→exporters）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`one of the world's largest exporters`（L2·PC）；`attract foreign investment`（L2·PC）。"}, {"term": "", "zh": "", "cn": "同时,它也在海外投资数十亿美元。", "en": "At the same time, it has also been investing billions of dollars overseas.", "ptype": "真题", "cat": "真题A", "map": "中国经济发展（工业革命·出口·第二大经济体）", "set": "CET4 2015·06·S1", "src": "CET4 2015·06·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;时锚:同时→一般现在/现在完成进行时;话题:补主语(→it，指中国);文化:海外投资→invest overseas；备注:[原卷如此]（\"同时,\"为半角逗号，照抄不改）", "ta": "补主语（回指 China）；时间状语前置（At the same time，连淑能 1993）；时态呼应（现在完成进行时）。", "te": "数字转换（\"数十亿美元\"→billions of dollars）；增补（also）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`billions of dollars`（L2·PC）；`invest overseas`（L2·PC）。"}, {"term": "", "zh": "", "cn": "2011年，中国超越日本成为世界第二大经济体。", "en": "In 2011, China surpassed Japan to become the world's second-largest economy.", "ptype": "真题", "cat": "真题A", "map": "中国经济发展（工业革命·出口·第二大经济体）", "set": "CET4 2015·06·S1", "src": "CET4 2015·06·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;时锚:2011年(过去)→一般过去时;话题:补主语(→China);文化:第二大经济体→the world's second-largest economy；超越→surpass/overtake", "ta": "补主语；时间状语前置（In 2011，连淑能 1993）；结果状语（to become…，连淑能 1993）。", "te": "增补（the world's）；惯用等值（\"超越…成为\"→surpassed … to become）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"第二大经济体\"官方行文 the world's second-largest economy 见 China Daily/新华（S1）。", "rp": "`the second-largest economy`（L2·PC）；`surpass/overtake`（L2·PC）；`V + to become …`（结果，L2·SB）→ 本句实例：China surpassed Japan to become the world's second-largest economy。"}, {"term": "", "zh": "", "cn": "据报道，今年中国快递服务（courier services)将递送大约 120 亿件包裹。", "en": "It is reported that China's courier services will deliver about 12 billion parcels this year.", "ptype": "真题", "cat": "真题A", "map": "快递", "set": "CET4 2015·06·S2", "src": "CET4 2015·06·S2", "cls": "Chapter 11", "tip": "断句:分句①\"据报道\"/②\"中国快递服务将递送…包裹\";核心=②;①→插入语(It is reported that…);时锚:今年/将→一般将来时;话题:补主语(→China's courier services);文化:快递服务→原卷括注 courier services(同源优先)；包裹→parcels；备注:[原卷如此]（括注\"（courier services)\"为全角左括号＋半角右括号，照抄不改）", "ta": "形式主语（It is reported that…，连淑能 1993）；补主语；时态呼应（一般将来时）。", "te": "数字转换（\"120 亿件\"→12 billion parcels）；增补（about）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"快递服务\"从原卷括注 courier services（同源优先），S1/同源。", "rp": "`It is reported that …`（L2·SB）→ 本句实例：It is reported that China's courier services will deliver …；`deliver parcels`（L2·PC）。"}, {"term": "", "zh": "", "cn": "这将使中国有可能超越美国成为世界上最大的快递市场。", "en": "This will make it possible for China to surpass the United States and become the world's largest express delivery market.", "ptype": "真题", "cat": "真题A", "map": "快递", "set": "CET4 2015·06·S2", "src": "CET4 2015·06·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;触发[使…有可能]→make it possible for + O + to do|enable + O + to do;时锚:将→一般将来时;话题:补主语(→This);文化:快递市场→express delivery market", "ta": "补主语；使役转移（\"使…有可能\"→make it possible for … to do，连淑能 1993）；形式宾语（it）。", "te": "增补（the world's）；动词并列（\"超越…成为\"→surpass … and become）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`make it possible for sb to do`（L2·SB）→ 本句实例：This will make it possible for China to surpass …；`express delivery market`（L2·PC）。"}, {"term": "", "zh": "", "cn": "大多数包裹里装着网上订购的物品。", "en": "Most parcels contain items ordered online.", "ptype": "真题", "cat": "真题A", "map": "快递", "set": "CET4 2015·06·S2", "src": "CET4 2015·06·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:处所话题→主语转换(Most parcels contain…)|存现句(There are…);文化:网上订购→ordered online", "ta": "话题→主语（\"包裹里装着\"→Most parcels contain，Li & Thompson 1976）；修饰语后置（ordered online）。", "te": "词性转换（\"装着\"→contain）；过去分词后置（\"网上订购的物品\"→items ordered online）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`items ordered online`（L2·PC）；`N + V-ed`（过去分词后置定语，L2·SB）→ 本句实例：items ordered online。"}, {"term": "", "zh": "", "cn": "中国给数百万在线零售商以极具竞争力的价格销售商品的机会。", "en": "China gives millions of online retailers the opportunity to sell goods at highly competitive prices.", "ptype": "真题", "cat": "真题A", "map": "快递", "set": "CET4 2015·06·S2", "src": "CET4 2015·06·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→China);文化:在线零售商→online retailers；极具竞争力的价格→highly competitive prices", "ta": "补主语；双宾结构（give sb sth）；修饰语后置（at … prices）。", "te": "增补（the）；词性转换（\"给…机会\"→gives … the opportunity to…）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`give sb the opportunity to V`（L2·PC）；`at competitive prices`（L2·PC）。"}, {"term": "", "zh": "", "cn": "仅在 11 月 11 日，中国消费者就从国内最大的购物平台购买了价值 90 亿美元的商品。", "en": "On November 11 alone, Chinese consumers bought goods worth 9 billion US dollars from the country's largest shopping platform.", "ptype": "真题", "cat": "真题A", "map": "快递", "set": "CET4 2015·06·S2", "src": "CET4 2015·06·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;时锚:仅…就(过去)→一般过去时;话题:补主语(→Chinese consumers);文化:购物平台→shopping platform；11月11日→November 11", "ta": "补主语；时间状语前置（On November 11 alone，连淑能 1993）；修饰语后置（worth …）。", "te": "数字转换（\"90 亿美元\"→9 billion US dollars）；增补（alone）；词性转换（\"价值…的商品\"→goods worth …）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`goods worth …`（L2·PC）；`shopping platform`（L2·PC）；`On … alone, S + V`（L2·SB）→ 本句实例：On November 11 alone, Chinese consumers bought goods worth …。"}, {"term": "", "zh": "", "cn": "中国有不少这样的特殊购物日。", "en": "China has quite a few such special shopping days.", "ptype": "真题", "cat": "真题A", "map": "快递", "set": "CET4 2015·06·S2", "src": "CET4 2015·06·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→China)|存现句(There are…);文化:购物日→shopping days", "ta": "补主语（话题→主语，Li & Thompson 1976）。", "te": "增补（quite / such）；惯用等值（\"不少\"→quite a few）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`quite a few`（L2·PC）；`shopping days`（L2·PC）。"}, {"term": "", "zh": "", "cn": "因此,快递业在中国扩展就不足为奇了。", "en": "Therefore, it is not surprising that the express delivery industry is expanding in China.", "ptype": "真题", "cat": "真题A", "map": "快递", "set": "CET4 2015·06·S2", "src": "CET4 2015·06·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;逻辑:因果→Therefore;时锚:一般现在时;话题:形式主语(it is not surprising that…)|动名词主语;文化:快递业→the express delivery industry；备注:[原卷如此]（\"因此,\"为半角逗号，照抄不改）", "ta": "形式主语（it is not surprising that…，连淑能 1993）；意合→形合（因果 Therefore，连淑能 1993）。", "te": "增补（it）；词性转换（\"扩展\"→is expanding）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`it is not surprising that …`（L2·SB）→ 本句实例：it is not surprising that the express delivery industry is expanding in China；`Therefore, …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "近年来，中国新能源汽车产业发展迅速。", "en": "In recent years, China's new energy vehicle industry has developed rapidly.", "ptype": "真题", "cat": "真题A", "map": "新能源汽车出口", "set": "CET4 2024·12·S3", "src": "CET4 2024·12·S3", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;时锚:近年来→现在完成时;话题:补主语(→China's new energy vehicle industry);文化:新能源汽车→S1 new energy vehicle (NEV)(教材术语库)", "ta": "补主语；时间状语前置（In recent years，连淑能 1993）；时态呼应（现在完成时）。", "te": "增补（rapidly）；词性转换（\"发展\"→developed）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"新能源汽车\"教材定译 new energy vehicle (NEV)（教材术语库，S1）。", "rp": "`new energy vehicle (NEV)`（L2·PC）；`develop rapidly`（L2·PC）。"}, {"term": "", "zh": "", "cn": "目前，中国新能源汽车年产量已高达近千万辆，占全球市场份额超过 60%，出口量不断创出新高。", "en": "At present, China's annual NEV output has reached nearly 10 million units, accounting for more than 60 percent of the global market share, with exports hitting new highs.", "ptype": "真题", "cat": "真题A", "map": "新能源汽车出口", "set": "CET4 2024·12·S3", "src": "CET4 2024·12·S3", "cls": "Chapter 11", "tip": "断句:分句①②③;核心=①;②→伴随状语(分词 accounting for…);③→独立主格(with exports hitting…);时锚:目前/已→现在完成时;话题:补主语(→China's annual NEV output);文化:新能源汽车→new energy vehicle (NEV)；市场份额→market share；出口量→export volume", "ta": "补主语；时间状语前置（At present）；分词状语（accounting for…）；独立主格（with exports hitting…，连淑能 1993）。", "te": "数字转换（\"近千万辆\"→nearly 10 million units；\"60%\"→60 percent）；惯用等值（\"创出新高\"→hitting new highs）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"新能源汽车\"教材定译 new energy vehicle (NEV)（教材术语库，S1）。", "rp": "`account for … percent`（L2·PC）；`hit new highs`（L2·PC）；`with + O + V-ing`（独立主格，L2·SB）→ 本句实例：… , accounting for … , with exports hitting new highs。"}, {"term": "", "zh": "", "cn": "中国政府通过加大资金投入和政策引导，鼓励新能源汽车企业进行技术创新，不断提高产品在市场上的竞争力。", "en": "By increasing capital investment and policy guidance, the Chinese government encourages new energy vehicle enterprises to carry out technological innovation and continuously improve the competitiveness of their products in the market.", "ptype": "真题", "cat": "真题A", "map": "新能源汽车出口", "set": "CET4 2024·12·S3", "src": "CET4 2024·12·S3", "cls": "Chapter 11", "tip": "断句:分句①②③;核心=②;①→方式状语(By increasing…);③→目的/结果(to…)|分词;话题:补主语(→The Chinese government);文化:资金投入→capital investment；政策引导→policy guidance；技术创新→technological innovation；竞争力→competitiveness", "ta": "补主语；方式状语前置（By increasing…，连淑能 1993）；目的宾语（encourages … to…）。", "te": "增补（by / continuously）；词性转换（\"加大投入\"→increasing investment；\"竞争力\"→competitiveness）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"新能源汽车\"教材定译 new energy vehicle (NEV)（教材术语库，S1）。", "rp": "`By V-ing, S + V`（L2·SB）→ 本句实例：By increasing capital investment and policy guidance, the Chinese government encourages …；`carry out innovation`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国新能源汽车产业的发展不仅有力推动了国内经济发展，也为全球新能源利用和环境保护做出了积极贡献。", "en": "The development of China's new energy vehicle industry has not only strongly boosted domestic economic development but also made positive contributions to global new energy utilization and environmental protection.", "ptype": "真题", "cat": "真题A", "map": "新能源汽车出口", "set": "CET4 2024·12·S3", "src": "CET4 2024·12·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=并列;触发[不仅…也…]→not only … but also …;话题:名词化主语(\"…产业的发展\"→The development of…);文化:新能源汽车→new energy vehicle (NEV)；环境保护→environmental protection；新能源利用→new energy utilization", "ta": "名词化主语（\"…产业的发展\"→The development of…）；意合→形合（递进 not only … but also …，连淑能 1993）；时态呼应（现在完成时）。", "te": "增补（strongly / positive）；惯用等值（\"做出贡献\"→made contributions to）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"新能源汽车\"教材定译 new energy vehicle (NEV)（教材术语库，S1）。", "rp": "`not only … but also …`（L2·SB）→ 本句实例：has not only strongly boosted … but also made positive contributions to …；`make contributions to`（L2·PC）。"}], "examsB": [{"term": "", "zh": "", "cn": "自从 1978 年启动改革以来，中国已从计划经济转为以市场为基础的经济，并经历了经济和社会的快速发展。", "en": "Since the launch of reform in 1978, China has transformed from a planned economy to a market-based economy and has experienced rapid economic and social development.", "ptype": "真题", "cat": "真题B", "map": "改革开放（计划经济→市场经济）", "set": "CET6 2014·12·S2", "src": "CET6 2014·12·S2", "cls": "Chapter 11", "tip": "断句:分句①\"自从1978年启动改革以来\"/②\"中国已从计划经济转为以市场为基础的经济\"/③\"并经历了…快速发展\";核心=②;①→时间状语从句(Since the reform was launched in 1978)|介词短语(Since the launch of reform in 1978);③→并列谓语(and has experienced…);时锚:自从…以来/已→现在完成时;话题:补主语(→China);文化:改革开放→S1 reform and opening up(库/教材术语库)；计划经济→planned economy(教材术语库)；市场经济→market economy(教材术语库)", "ta": "补主语（话题→主语，Li & Thompson 1976）；时间状语从句前置（连淑能 1993）；时态呼应（现在完成时，连淑能 1993）；意合→形合（分句③并列谓语 and）。", "te": "词性转换（\"转为…经济\"→transformed from … to …）；增补（rapid）；动词名物化（\"启动\"→the launch of，Molina & Albir 2002）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"改革开放\"对应官方定译见教材术语库/官方英文站（reform and opening up，S1）；\"计划经济\"planned economy、\"市场经济\"market economy 见教材术语库（S1）。", "rp": "`transform from A to B`（L2·PC）；`have experienced … development`（L2·PC）；`Since …, S + have + V-ed`（L2·SB）→ 本句实例：Since the launch of reform in 1978, China has transformed …。"}, {"term": "", "zh": "", "cn": "年均10%的 GDP 增长已使五亿多人脱贫。", "en": "GDP growth averaging 10 percent a year has lifted more than 500 million people out of poverty.", "ptype": "真题", "cat": "真题B", "map": "改革开放（计划经济→市场经济）", "set": "CET6 2014·12·S2", "src": "CET6 2014·12·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;触发[使]→have lifted + O + out of poverty|enable + O + to …;时锚:已→现在完成时;话题:话题主语化(\"年均10%的GDP增长\"→GDP growth averaging 10 percent a year);文化:脱贫→S1 lift … out of poverty(官媒)；GDP→GDP", "ta": "补主语（话题→主语，Li & Thompson 1976）；使役转移（\"已使…脱贫\"→has lifted … out of poverty，连淑能 1993）；时态呼应（现在完成时）。", "te": "词性转换（\"年均10%\"→averaging 10 percent a year，分词化）；增补（more than）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"脱贫\"官方行文多作 lift … out of poverty，见 gov 英文版/China Daily（S1）。", "rp": "`lift … out of poverty`（L2·PC）；`average … percent a year`（L2·PC）；`N + V-ing …`（分词后置定语，L2·SB）→ 本句实例：GDP growth averaging 10 percent a year …。"}, {"term": "", "zh": "", "cn": "联合国的“千年(millennium)发展目标”在中国均已达到或即将达到。", "en": "The UN's Millennium Development Goals have all been met or are about to be met in China.", "ptype": "真题", "cat": "真题B", "map": "改革开放（计划经济→市场经济）", "set": "CET6 2014·12·S2", "src": "CET6 2014·12·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:受事→被动(→have been met);文化:千年发展目标→Millennium Development Goals(原卷括注 millennium，同源优先，官方搭配 MDGs)；联合国→the United Nations", "ta": "受事主语→被动（have been met，CL-04）；意合→形合（\"均…或即将…\"→并列谓语）。", "te": "增补（all / in China）；惯用等值（\"即将达到\"→are about to be met）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"千年发展目标\"从原卷括注 millennium，取官方搭配 Millennium Development Goals（联合国 MDGs），S1/同源。", "rp": "`Millennium Development Goals`（L2·PC）；`be about to V`（L2·PC）；`have been V-ed or are about to be V-ed`（L2·SB）→ 本句实例：… have all been met or are about to be met in China。"}, {"term": "", "zh": "", "cn": "目前，中国的第十二个五年规划强调发展服务业和解决环境及社会不平衡的问题。", "en": "At present, China's 12th Five-Year Plan emphasizes developing the service sector and addressing environmental and social imbalances.", "ptype": "真题", "cat": "真题B", "map": "改革开放（计划经济→市场经济）", "set": "CET6 2014·12·S2", "src": "CET6 2014·12·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;时锚:目前→一般现在时;话题:补主语(→China's 12th Five-Year Plan);文化:五年规划→Five-Year Plan(官方)；服务业→the service sector", "ta": "补主语；时间状语前置（At present，连淑能 1993）；名词化（\"发展\"→developing）。", "te": "词性转换（\"不平衡\"→imbalances）；增补（and）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"五年规划\"官方定式 Five-Year Plan 见 gov 英文版（S1）。", "rp": "`Five-Year Plan`（L2·PC）；`address imbalances`（L2·PC）；`emphasize V-ing`（L2·PC）。"}, {"term": "", "zh": "", "cn": "政府已设定目标减少污染，提高能源效率，改善得到教育和医保的机会，并扩大社会保障。", "en": "The government has set goals to reduce pollution, improve energy efficiency, improve access to education and medical insurance, and expand social security.", "ptype": "真题", "cat": "真题B", "map": "改革开放（计划经济→市场经济）", "set": "CET6 2014·12·S2", "src": "CET6 2014·12·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;时锚:已→现在完成时;话题:补主语(→The government);触发[设定目标…]→has set goals to V…;文化:能源效率→energy efficiency；医保→medical insurance(S4)；社会保障→social security(S1)", "ta": "补主语；时态呼应（现在完成时，连淑能 1993）；目的状语（to V…，连淑能 1993）。", "te": "增补（access to）；动词并列（reduce / improve / expand）；词性转换（\"得到…机会\"→access to）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"社会保障\"官方定译 social security 见 gov 英文版（S1）。", "rp": "`set goals to V`（L2·PC）；`improve access to`（L2·PC）；`V1, V2, V3, and V4`（L2·SB）→ 本句实例：to reduce pollution, improve energy efficiency, improve access to …, and expand social security。"}, {"term": "", "zh": "", "cn": "中国现在 7%的经济年增长目标表明政府意在重视生活质量而不是增长速度。", "en": "China's current annual economic growth target of 7 percent indicates that the government intends to focus on the quality of life rather than the growth rate.", "ptype": "真题", "cat": "真题B", "map": "改革开放（计划经济→市场经济）", "set": "CET6 2014·12·S2", "src": "CET6 2014·12·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;触发[不是…而是]→rather than|instead of;话题:补主语(→China's annual economic growth target of 7 percent);文化:生活质量→quality of life(S1)；增长速度→growth rate；备注:[原卷如此]（\"现在 7%\"处夹半角空格，照抄不改）", "ta": "补主语（话题→主语，Li & Thompson 1976）；意合→形合（\"表明\"→that 宾语从句）；对比显性化（rather than）。", "te": "词性转换（\"意在重视\"→intends to focus on）；惯用等值（\"不是…而是\"→rather than）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"生活质量\"官方行文 quality of life 见 China Daily/新华（S1）。", "rp": "`a growth target of … percent`（L2·PC）；`focus on … rather than …`（L2·PC）；`indicate that …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "注意：此部分试题请在答题卡 2 上作答。", "en": "Note: Please answer this part of the test on Answer Sheet 2.", "ptype": "真题", "cat": "真题B", "map": "改革开放（计划经济→市场经济）", "set": "CET6 2014·12·S2", "src": "CET6 2014·12·S2", "cls": "Chapter 11", "tip": "断句:单句(试卷指令，非语篇);核心=①;话题:无主句→祈使句(补 Please);备注:[试卷指令，非语篇内容，照抄保留]", "ta": "无主句→祈使句（补 Please，连淑能 1993）。", "te": "增补（Please）；词性转换（\"作答\"→answer）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`on Answer Sheet 2`（L2·PC）。"}, {"term": "", "zh": "", "cn": "电子商务的蓬勃发展正在深刻改变中国农村的面貌。", "en": "The booming development of e-commerce is profoundly changing the face of rural China.", "ptype": "真题", "cat": "真题B", "map": "农村电商（乡村振兴）", "set": "CET6 2026·06·S2", "src": "CET6 2026·06·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:名词化主语(\"…的蓬勃发展\"→The booming development of…);时锚:正在→现在进行时;文化:电子商务→e-commerce(教材术语库/库)；农村→rural areas", "ta": "名词化主语（\"…的蓬勃发展\"→The booming development of…，连淑能 1993）；时态呼应（现在进行时，连淑能 1993）。", "te": "词性转换（\"改变\"→changing；\"面貌\"→the face of）；增补（profoundly）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"电子商务\"教材定译/官方行文 e-commerce（教材术语库/CGTN，S1）。", "rp": "`the booming development of`（L2·PC）；`change the face of`（L2·PC）；`be V-ing …`（进行体，L2·SB）→ 本句实例：is profoundly changing the face of rural China。"}, {"term": "", "zh": "", "cn": "随着互联网和物流网络快速向农村延伸，越来越多的农村居民通过电子商务平台将农产品直接销售给城市消费者。", "en": "As the Internet and logistics networks rapidly extend into rural areas, more and more rural residents are selling agricultural products directly to urban consumers through e-commerce platforms.", "ptype": "真题", "cat": "真题B", "map": "农村电商（乡村振兴）", "set": "CET6 2026·06·S2", "src": "CET6 2026·06·S2", "cls": "Chapter 11", "tip": "断句:分句①\"随着…向农村延伸\"/②\"农村居民…销售\";核心=②;①→背景状语从句(As…);时锚:随着→一般现在时;话题:补主语(→more and more rural residents);文化:物流→logistics；农产品→agricultural products；电子商务平台→e-commerce platforms", "ta": "补主语；背景状语从句前置（As…，连淑能 1993）；意合→形合。", "te": "增补（directly / more and more）；词性转换（\"延伸\"→extend into）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"电子商务\"官方行文 e-commerce（S1）。", "rp": "`as … extends into`（L2·PC）；`sell … directly to`（L2·PC）；`As …, 主句`（L2·SB）→ 本句实例：As the Internet and logistics networks rapidly extend into rural areas, more and more rural residents are selling …。"}, {"term": "", "zh": "", "cn": "近年来，直播带货 (live-streamingcommerce) 使城市消费者能够与卖家实时互动，已成为促进农村发展的一种新方式。", "en": "In recent years, livestream sales have enabled urban consumers to interact with sellers in real time and have become a new way to promote rural development.", "ptype": "真题", "cat": "真题B", "map": "农村电商（乡村振兴）", "set": "CET6 2026·06·S2", "src": "CET6 2026·06·S2", "cls": "Chapter 11", "tip": "断句:分句①\"直播带货使…互动\"/②\"已成为…新方式\";核心=①;②→并列谓语(and has become…);时锚:近年来/已→现在完成时;话题:补主语(→Livestream sales);触发[使…能够]→enable/allow + O + to do|let + O + do;文化:直播带货→S1 livestream sales(原卷括注 live-streamingcommerce，同源优先/库)；农村发展→rural development；备注:[原卷如此]（括注 live-streamingcommerce 中 streaming 与 commerce 之间无空格，照抄不改）", "ta": "补主语；时态呼应（现在完成时，连淑能 1993）；使役转移（\"使…能够互动\"→have enabled … to interact，连淑能 1993）。", "te": "增补（in real time / a new way）；词性转换（\"促进\"→to promote）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"直播带货\"原卷括注 live-streamingcommerce，库内一汉多译 livestream sales / livestream commerce（S1，CGTN/China Daily 高频）。", "rp": "`enable sb to do`（L2·PC）；`interact with`（L2·PC）；`a new way to V`（L2·PC）。"}, {"term": "", "zh": "", "cn": "电子商务打破了城乡之间的信息壁垒，拓宽了农产品销售渠道，帮助农村居民增收致富。", "en": "E-commerce has broken down the information barriers between urban and rural areas, broadened sales channels for agricultural products, and helped rural residents increase their incomes.", "ptype": "真题", "cat": "真题B", "map": "农村电商（乡村振兴）", "set": "CET6 2026·06·S2", "src": "CET6 2026·06·S2", "cls": "Chapter 11", "tip": "断句:分句①②③;核心=①;②③→并列谓语;话题:补主语(→E-commerce);文化:城乡→urban and rural (areas)；信息壁垒→information barriers；销售渠道→sales channels；增收致富→increase incomes(S4)", "ta": "补主语；意合→形合（三谓语并列 and，连淑能 1993）；时态呼应（现在完成时）。", "te": "收敛冗余（\"增收致富\"→increase their incomes，简洁原则）；增补（between…and…）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"电子商务\"官方行文 e-commerce（S1）；\"增收致富\"无白名单定译，标 S4（increase incomes）。", "rp": "`break down barriers`（L2·PC）；`broaden channels`（L2·PC）；`V1, V2 and V3`（L2·SB）→ 本句实例：has broken down …, broadened …, and helped …。"}, {"term": "", "zh": "", "cn": "数字经济与乡村振兴的深度融合，正在为中国农村发展注入前所未有的活力。", "en": "The deep integration of the digital economy and rural revitalization is injecting unprecedented vitality into China's rural development.", "ptype": "真题", "cat": "真题B", "map": "农村电商（乡村振兴）", "set": "CET6 2026·06·S2", "src": "CET6 2026·06·S2", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:名词化主语(\"…的深度融合\"→The deep integration of…);时锚:正在→现在进行时;文化:数字经济→digital economy(教材术语库)；乡村振兴→S1 rural revitalization(库)", "ta": "名词化主语（\"…的深度融合\"→The deep integration of…，连淑能 1993）；时态呼应（现在进行时）。", "te": "名词化（\"融合\"→integration）；增补（unprecedented）；惯用等值（\"注入活力\"→inject vitality into）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"数字经济\"教材定译 digital economy（教材术语库，S1）；\"乡村振兴\"官方定译 rural revitalization 见 gov/新华（S1，库内已收敛）。", "rp": "`inject vitality into`（L2·PC）；`the integration of A and B`（L2·PC）；`be V-ing … into`（L2·SB）→ 本句实例：is injecting unprecedented vitality into China's rural development。"}, {"term": "", "zh": "", "cn": "深圳是中国广东省一座新开发的城市。", "en": "Shenzhen is a newly developed city in Guangdong Province, China.", "ptype": "真题", "cat": "真题B", "map": "深圳", "set": "CET6 2016·06·S3", "src": "CET6 2016·06·S3", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→Shenzhen);文化:深圳→Shenzhen(专名)；广东省→Guangdong Province", "ta": "补主语；修饰语后置（in Guangdong Province, China）。", "te": "词性转换（\"新开发的\"→newly developed）；增补（a）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`a newly developed city`（L2·PC）；`in … Province`（L2·PC）。"}, {"term": "", "zh": "", "cn": "在改革开放之前，深圳不过是一个渔村，仅有三万多人。", "en": "Before reform and opening up, Shenzhen was no more than a fishing village with a population of just over 30,000.", "ptype": "真题", "cat": "真题B", "map": "深圳", "set": "CET6 2016·06·S3", "src": "CET6 2016·06·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→伴随介词短语(with a population of…);时锚:改革开放之前(过去)→一般过去时;话题:补主语(→Shenzhen);文化:改革开放→S1 reform and opening up(库/教材)；渔村→fishing village", "ta": "补主语；时间状语前置（Before reform and opening up，连淑能 1993）；伴随介词短语（with a population of…）。", "te": "惯用等值（\"不过是\"→no more than）；数字转换（\"三万多人\"→just over 30,000）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"改革开放\"官方定译 reform and opening up（教材术语库/官方英文站，S1）。", "rp": "`before reform and opening up`（L2·PC）；`with a population of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "20 世纪80 年代，中国政府创建了深圳经济特区，作为实施社会主义市场经济的试验田。", "en": "In the 1980s, the Chinese government established the Shenzhen Special Economic Zone as a testing ground for implementing the socialist market economy.", "ptype": "真题", "cat": "真题B", "map": "深圳", "set": "CET6 2016·06·S3", "src": "CET6 2016·06·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→状语(as a testing ground for…);时锚:20世纪80年代(过去)→一般过去时;话题:补主语(→the Chinese government);文化:经济特区→special economic zone(教材增补)；社会主义市场经济→socialist market economy(教材术语库)；备注:[原卷如此]（\"20 世纪80 年代\"中 20 与 世纪、80 与 年代之间夹半角空格，照抄不改）", "ta": "补主语；时间状语前置（In the 1980s，连淑能 1993）；状语（as a testing ground for…）。", "te": "动词转译（\"创建\"→established；\"实施\"→implementing，动名词承接 for）；增补（the）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"经济特区\"教材定译 special economic zone（教材术语库，S1）；\"社会主义市场经济\"教材定译 socialist market economy（教材术语库，S1）。", "rp": "`Special Economic Zone`（L2·PC）；`as a testing ground for`（L2·PC）；`implement the … economy`（L2·PC）。"}, {"term": "", "zh": "", "cn": "如今，深圳人口已经超过 1000万，整个城市发生了巨大的变化。", "en": "Today, Shenzhen's population has exceeded 10 million, and the whole city has undergone tremendous changes.", "ptype": "真题", "cat": "真题B", "map": "深圳", "set": "CET6 2016·06·S3", "src": "CET6 2016·06·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→并列谓语(and the whole city has…);时锚:如今/已经…了→现在完成时;话题:补主语(→Shenzhen's population);文化:人口→population", "ta": "补主语；时间状语前置（Today，连淑能 1993）；意合→形合（并列谓语 and）；时态呼应（现在完成时）。", "te": "数字转换（\"1000万\"→10 million）；词性转换（\"发生…变化\"→undergone changes）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`have undergone changes`（L2·PC）；`exceed … million`（L2·PC）。"}, {"term": "", "zh": "", "cn": "到 2014 年，深圳的人均（per-capita）GDP 已达 25000 美元，相当于世界上一些发达国家的水平。", "en": "By 2014, Shenzhen's per-capita GDP had reached 25,000 US dollars, equivalent to that of some developed countries in the world.", "ptype": "真题", "cat": "真题B", "map": "深圳", "set": "CET6 2016·06·S3", "src": "CET6 2016·06·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→伴随状语(equivalent to…);时锚:到2014年/已达→过去完成时;话题:补主语(→Shenzhen's per-capita GDP);文化:人均GDP→原卷括注 per-capita(同源优先)；发达国家→developed countries", "ta": "补主语；时间状语前置（By 2014，连淑能 1993）；伴随状语（equivalent to…）；时态呼应（过去完成时）。", "te": "数字转换（\"25000 美元\"→25,000 US dollars）；惯用等值（\"相当于…水平\"→equivalent to that of…）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"人均\"从原卷括注 per-capita（同源优先）。", "rp": "`per-capita GDP`（L2·PC）；`be equivalent to`（L2·PC）；`By …, S + had + V-ed`（L2·SB）→ 本句实例：By 2014, Shenzhen's per-capita GDP had reached …。"}, {"term": "", "zh": "", "cn": "就综合经济实力而言，深圳居于中国顶尖城市之列。", "en": "In terms of overall economic strength, Shenzhen ranks among the top cities in China.", "ptype": "真题", "cat": "真题B", "map": "深圳", "set": "CET6 2016·06·S3", "src": "CET6 2016·06·S3", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:句首框架话题\"就…而言\"→介词短语(In terms of…);补主语(→Shenzhen);文化:综合经济实力→overall economic strength；顶尖城市→top cities", "ta": "话题→状语前置（\"就…而言\"→In terms of…，连淑能 1993）；补主语。", "te": "惯用等值（\"居于…之列\"→ranks among）；词性转换（\"实力\"→strength）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`In terms of`（L2·PC）；`rank among the top`（L2·PC）。"}, {"term": "", "zh": "", "cn": "由于其独特的地位，深圳也是国内外企业家创业的理想之地。", "en": "Because of its unique status, Shenzhen is also an ideal place for entrepreneurs at home and abroad to start businesses.", "ptype": "真题", "cat": "真题B", "map": "深圳", "set": "CET6 2016·06·S3", "src": "CET6 2016·06·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=②;①→原因状语(Because of…|Owing to…);话题:补主语(→Shenzhen);文化:国内外→domestic and overseas；企业家→entrepreneurs", "ta": "补主语；原因状语前置（Because of…，连淑能 1993）。", "te": "增补（also）；词性转换（\"创业\"→start businesses）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`an ideal place for sb to V`（L2·PC）；`at home and abroad`（L2·PC）。"}, {"term": "", "zh": "", "cn": "闻名于世的丝绸之路是一系列连接东西方的路线。", "en": "The world-famous Silk Road was a series of routes that connected the East and the West.", "ptype": "真题", "cat": "真题B", "map": "丝绸之路", "set": "CET6 2013·12·S1", "src": "CET6 2013·12·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→The world-famous Silk Road);受事定语前置→后置(\"连接东西方的\"→that connected…);文化:丝绸之路→S1 the Silk Road(教材术语库/库)", "ta": "补主语；定语从句后置（\"连接东西方的\"→that connected…，连淑能 1993）。", "te": "词性转换（\"闻名于世的\"→world-famous）；增补（the）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"丝绸之路\"官方定译 the Silk Road（教材术语库，S1）。", "rp": "`the Silk Road`（L2·PC）；`a series of routes`（L2·PC）；`N + that + V …`（定语从句，L2·SB）→ 本句实例：a series of routes that connected the East and the West。"}, {"term": "", "zh": "", "cn": "丝绸之路延伸6,000多公里，得名于古代中国的丝绸贸易。", "en": "The Silk Road extended for more than 6,000 kilometers, so named because of the silk trade in ancient China.", "ptype": "真题", "cat": "真题B", "map": "丝绸之路", "set": "CET6 2013·12·S1", "src": "CET6 2013·12·S1", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→原因状语(so named because of…);话题:补主语(→The Silk Road);文化:丝绸之路→S1 the Silk Road；丝绸贸易→silk trade", "ta": "补主语；原因状语（so named because of…）。", "te": "增补（more than / so）；词性转换（\"得名于\"→named because of）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"丝绸之路\"官方定译 the Silk Road（教材术语库，S1）。", "rp": "`extend for … kilometers`（L2·PC）；`be named because of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "丝绸之路上的贸易在中国、南亚、欧洲和中东文明发展中发挥了重要作用。", "en": "Trade along the Silk Road played an important role in the development of the civilizations of China, South Asia, Europe and the Middle East.", "ptype": "真题", "cat": "真题B", "map": "丝绸之路", "set": "CET6 2013·12·S1", "src": "CET6 2013·12·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→Trade along the Silk Road);文化:丝绸之路→S1 the Silk Road；中东→the Middle East；发挥了重要作用→play an important role in", "ta": "补主语；修饰语后置（along the Silk Road；of 短语连缀）。", "te": "惯用等值（\"发挥…作用\"→played a … role in）；词性转换（\"文明发展\"→the development of the civilizations）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"丝绸之路\"官方定译 the Silk Road（S1）。", "rp": "`play an important role in`（L2·PC）；`trade along …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "正是通过丝绸之路，中国的造纸、火药、指南针、印刷术等四大发明才被引介到世界各地。", "en": "It was through the Silk Road that China's Four Great Inventions — papermaking, gunpowder, the compass and printing — were introduced to the rest of the world.", "ptype": "真题", "cat": "真题B", "map": "丝绸之路", "set": "CET6 2013·12·S1", "src": "CET6 2013·12·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;触发[正是…才…]→It was through … that …(强调句);话题:受事→被动(were introduced);文化:四大发明→the Four Great Inventions(S1)；造纸→papermaking；火药→gunpowder；指南针→the compass；印刷术→printing；丝绸之路→S1 the Silk Road", "ta": "强调句（It was through … that …，连淑能 1993）；受事主语→被动（were introduced，CL-04）。", "te": "增补（the rest of）；惯用等值（\"被引介\"→were introduced to）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"四大发明\"官方行文 the Four Great Inventions 见 China Daily/新华（S1）；\"丝绸之路\"官方定译 the Silk Road（S1）。", "rp": "`It is/was … that …`（强调，L2·SB）→ 本句实例：It was through the Silk Road that … were introduced to the rest of the world；`the Four Great Inventions`（L2·PC）。"}, {"term": "", "zh": "", "cn": "同样，中国的丝绸、茶叶和瓷器(porcelain)也传遍全球。", "en": "Similarly, China's silk, tea and porcelain spread across the globe.", "ptype": "真题", "cat": "真题B", "map": "丝绸之路", "set": "CET6 2013·12·S1", "src": "CET6 2013·12·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;逻辑:并列→Similarly|Likewise;话题:补主语(→China's silk, tea and porcelain);文化:瓷器→原卷括注 porcelain(同源优先)；丝绸→silk；茶叶→tea", "ta": "补主语；意合→形合（并列 Similarly，连淑能 1993）。", "te": "惯用等值（\"传遍全球\"→spread across the globe）；增补（Similarly）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"瓷器\"从原卷括注 porcelain（同源优先），S1/同源。", "rp": "`spread across the globe`（L2·PC）；`silk, tea and porcelain`（L2·PC）。"}, {"term": "", "zh": "", "cn": "物质文化的交流是双向的，欧洲也通过丝绸之路出口各种商品和植物，满足中国市场的需要。", "en": "The exchange of material culture was two-way, and Europe also exported various goods and plants along the Silk Road to meet the needs of the Chinese market.", "ptype": "真题", "cat": "真题B", "map": "丝绸之路", "set": "CET6 2013·12·S1", "src": "CET6 2013·12·S1", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→并列分句(and Europe also exported…);逻辑:并列→and;话题:补主语(→The exchange of material culture / Europe);文化:物质文化→material culture；丝绸之路→S1 the Silk Road", "ta": "补主语；意合→形合（并列分句 and）；目的状语（to meet…）。", "te": "词性转换（\"交流\"→exchange；\"双向的\"→two-way）；增补（also）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"丝绸之路\"官方定译 the Silk Road（S1）。", "rp": "`the exchange of material culture`（L2·PC）；`meet the needs of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "张骞(Zhang Qian)是中国第一个伟大的探险家。", "en": "Zhang Qian was China's first great explorer.", "ptype": "真题", "cat": "真题B", "map": "张骞", "set": "CET6 2023·03·S1", "src": "CET6 2023·03·S1", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→Zhang Qian);文化:张骞→原卷括注 Zhang Qian(同源优先)", "ta": "补主语；修饰语前置（China's first great）。", "te": "增补（China's）；词性转换（\"探险家\"→explorer）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"张骞\"从原卷括注 Zhang Qian（同源优先，S1/同源）。", "rp": "`China's first great explorer`（L2·PC）。"}, {"term": "", "zh": "", "cn": "他不畏艰险，克服重重困难，两次出使西域，开通了中国同西亚和欧洲的通商关系，将中国的丝和丝织品运往西亚和欧洲，开拓了历史上著名的“丝绸之路”。", "en": "Braving dangers and overcoming numerous difficulties, he made two missions to the Western Regions, opened up trade relations between China and West Asia and Europe, carried China's silk and silk fabrics to West Asia and Europe, and pioneered the world-famous Silk Road.", "ptype": "真题", "cat": "真题B", "map": "张骞", "set": "CET6 2023·03·S1", "src": "CET6 2023·03·S1", "cls": "Chapter 11", "tip": "断句:分句①②③④⑤⑥;核心=③\"两次出使西域\";①②→伴随状语(分词 Braving… overcoming…);④⑤⑥→并列谓语;话题:承前补主语(→he);文化:西域→the Western Regions(S1)；丝绸之路→S1 the Silk Road；西亚→West Asia；丝织品→silk fabrics", "ta": "承前补主语（→he）；分词状语（Braving… overcoming…，连淑能 1993）；意合→形合（并列谓语 and）。", "te": "收敛冗余（\"不畏艰险\"→Braving dangers）；动词并列（made / opened up / carried / pioneered）；增补（numerous）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"西域\"官方行文 the Western Regions 见 China Daily（S1）；\"丝绸之路\"官方定译 the Silk Road（教材术语库，S1）。", "rp": "`Braving … and overcoming …, S + V`（L2·SB）→ 本句实例：Braving dangers and overcoming numerous difficulties, he made two missions …；`open up trade relations`（L2·PC）。"}, {"term": "", "zh": "", "cn": "同时，他又将西域的风土人情、地理文化以及特有物种等介绍到中原，极大地开阔了人们的视野。", "en": "Meanwhile, he also introduced the customs, geography and culture as well as unique species of the Western Regions to the Central Plains, greatly broadening people's horizons.", "ptype": "真题", "cat": "真题B", "map": "张骞", "set": "CET6 2023·03·S1", "src": "CET6 2023·03·S1", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→结果状语(分词 greatly broadening…)(CL-03);逻辑:并列→Meanwhile;话题:补主语(→he);文化:西域→the Western Regions；中原→the Central Plains(S1)", "ta": "承前补主语；分词状语（greatly broadening…，连淑能 1993）；意合→形合。", "te": "增补（also / greatly）；词性转换（\"开阔…视野\"→broadening … horizons）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"西域\"官方行文 the Western Regions（S1）；\"中原\"官方行文 the Central Plains 见 China Daily/新华（S1）。", "rp": "`broaden one's horizons`（L2·PC）；`customs and culture`（L2·PC）；`V-ing 状语`（L2·SB）→ 本句实例：…, greatly broadening people's horizons。"}, {"term": "", "zh": "", "cn": "正如历史学家所指出的那样，如果没有张骞出使西域，就不可能有丝绸之路的开辟，也就不会有汉朝同西域或欧洲的文化交流。", "en": "As historians have pointed out, without Zhang Qian's missions to the Western Regions, there would have been no opening of the Silk Road, nor any cultural exchange between the Han Dynasty and the Western Regions or Europe.", "ptype": "真题", "cat": "真题B", "map": "张骞", "set": "CET6 2023·03·S1", "src": "CET6 2023·03·S1", "cls": "Chapter 11", "tip": "断句:分句①②③;核心=②（虚拟主句）;①→方式/插入状语(As historians have pointed out, …);②③→虚拟条件(without…)＋结果;逻辑:虚拟假设→without…|If it had not been for…;文化:西域→the Western Regions；汉朝→the Han Dynasty(教材增补)", "ta": "插入状语前置（As…，连淑能 1993）；虚拟语气（there would have been…，连淑能 1993）。", "te": "惯用等值（\"如果没有…就不可能有\"→without…, there would have been no…）；增补（nor any）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"西域\"官方行文 the Western Regions（S1）；\"汉朝\"教材定译 the Han Dynasty（教材术语库，S1）。", "rp": "`As … have pointed out, …`（L2·SB）→ 本句实例：As historians have pointed out, without … there would have been no …；`there would have been no …`（虚拟，L2·SB）。"}, {"term": "", "zh": "", "cn": "郑和是中国历史上最杰出的航海家，在航海、外交、军事等诸多领域都表现出非凡的智慧和卓越的才能。", "en": "Zheng He was the most outstanding navigator in Chinese history and displayed extraordinary wisdom and outstanding talent in many fields such as navigation, diplomacy and military affairs.", "ptype": "真题", "cat": "真题B", "map": "郑和", "set": "CET6 2023·03·S2", "src": "CET6 2023·03·S2", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→并列谓语(and displayed…);话题:补主语(→Zheng He);文化:郑和→Zheng He(专名)；航海家→navigator", "ta": "补主语；意合→形合（并列谓语 and）。", "te": "增补（such as）；词性转换（\"表现出…才能\"→displayed … talent）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`display talent/wisdom`（L2·PC）；`in fields such as …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "他曾七次率领庞大的船队远航，访问了西太平洋和印度洋的许多国家和地区，加深了中国同东南亚、东非的相互了解。", "en": "He led a huge fleet on seven voyages, visited many countries and regions in the Western Pacific and the Indian Ocean, and deepened mutual understanding between China and Southeast Asia and East Africa.", "ptype": "真题", "cat": "真题B", "map": "郑和", "set": "CET6 2023·03·S2", "src": "CET6 2023·03·S2", "cls": "Chapter 11", "tip": "断句:分句①②③;核心=①;②③→并列谓语;时锚:曾(过去)→一般过去时;话题:补主语(→He);文化:船队→fleets；西太平洋→the Western Pacific；印度洋→the Indian Ocean；东南亚→Southeast Asia；东非→East Africa", "ta": "承前补主语；时态呼应（一般过去时）；意合→形合（三谓语并列 and）。", "te": "增补（on seven voyages）；词性转换（\"访问\"→visited；\"加深\"→deepened）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`lead a fleet`（L2·PC）；`deepen mutual understanding`（L2·PC）；`V1, V2 and V3`（L2·SB）→ 本句实例：led a huge fleet …, visited …, and deepened …。"}, {"term": "", "zh": "", "cn": "郑和下西洋对中外的经济和文化交流起到了十分积极的推进作用，也为维护区域和平做出了巨大的贡献。", "en": "Zheng He's voyages to the Western Seas played a very positive role in promoting economic and cultural exchanges between China and foreign countries, and also made great contributions to safeguarding regional peace.", "ptype": "真题", "cat": "真题B", "map": "郑和", "set": "CET6 2023·03·S2", "src": "CET6 2023·03·S2", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→并列谓语(and made a great contribution to…);话题:名词化主语(\"郑和下西洋\"→Zheng He's voyages to the Western Seas);文化:下西洋→voyages to the Western Seas(S1)；区域和平→regional peace", "ta": "名词化主语（\"郑和下西洋\"→Zheng He's voyages to the Western Seas）；意合→形合（并列谓语 and）。", "te": "惯用等值（\"起到了…推进作用\"→played a … role in promoting；\"做出了…贡献\"→made contributions to）；增补（also）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"下西洋\"官方行文 the voyages to the Western Seas 见 China Daily/新华（S1）。", "rp": "`play a positive role in V-ing`（L2·PC）；`make contributions to`（L2·PC）；`safeguard regional peace`（L2·PC）。"}, {"term": "", "zh": "", "cn": "为了永远铭记郑和及其丰功伟绩，7月11日，即郑和首次率船队远航启程的日子，被定为中国的航海节。", "en": "To forever remember Zheng He and his great achievements, July 11, the day when he first led his fleet on a voyage, was designated as China's Maritime Day.", "ptype": "真题", "cat": "真题B", "map": "郑和", "set": "CET6 2023·03·S2", "src": "CET6 2023·03·S2", "cls": "Chapter 11", "tip": "断句:分句①②;核心=②\"7月11日被定为航海节\";①→目的状语(To forever remember…);②→被动(was designated as…)+同位语(即…);文化:航海节→China's Maritime Day(S1)", "ta": "目的状语前置（To forever remember…，连淑能 1993）；受事主语→被动（was designated as，CL-04）；同位语（the day when…）。", "te": "惯用等值（\"被定为\"→was designated as）；增补（his）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"航海节\"官方行文 China's Maritime Day 见 China Daily/新华（S1）。", "rp": "`be designated as`（L2·PC）；`To V …, S + be V-ed`（目的+被动，L2·SB）→ 本句实例：To forever remember …, July 11 … was designated as …；`the day when …`（L2·SB）。"}, {"term": "", "zh": "", "cn": "近年来，越来越多的中国文化产品走向全球市场，日益受到海外消费者的青睐。", "en": "In recent years, more and more Chinese cultural products have entered the global market, increasingly favored by overseas consumers.", "ptype": "真题", "cat": "真题B", "map": "文化产品出海", "set": "CET6 2023·06·S2", "src": "CET6 2023·06·S2", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→伴随状语(分词 increasingly favored by…);时锚:近年来→现在完成时;话题:补主语(→more and more Chinese cultural products);文化:文化产品→cultural products；海外消费者→overseas consumers", "ta": "补主语；时间状语前置（In recent years，连淑能 1993）；分词状语（increasingly favored by…，连淑能 1993）；时态呼应（现在完成时）。", "te": "增补（increasingly）；惯用等值（\"受到…青睐\"→favored by）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`enter the global market`（L2·PC）；`be favored by`（L2·PC）；`V-ing 状语`（L2·SB）→ 本句实例：…, increasingly favored by overseas consumers。"}, {"term": "", "zh": "", "cn": "随着中国对外文化贸易的快速发展，中国文化产品出口额已持续多年位居世界前列，形成了一批具有国际影响力的文化企业、产品和品牌。", "en": "With the rapid development of China's foreign cultural trade, the export volume of Chinese cultural products has ranked among the world's top for many years, forming a number of cultural enterprises, products and brands with international influence.", "ptype": "真题", "cat": "真题B", "map": "文化产品出海", "set": "CET6 2023·06·S2", "src": "CET6 2023·06·S2", "cls": "Chapter 11", "tip": "断句:分句①②③;核心=②;①→背景状语(With the rapid development of…);③→结果状语(分词 forming…);文化:对外文化贸易→foreign cultural trade；出口额→export volume；品牌→brands", "ta": "背景状语前置（With the rapid development of…，连淑能 1993）；分词状语（forming…，连淑能 1993）；时态呼应（现在完成时）。", "te": "增补（a number of）；惯用等值（\"位居世界前列\"→ranked among the world's top）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"随着…的发展\"库内作 with the rapid development of …（S3，库）。", "rp": "`with the rapid development of`（L2·PC，库 S3）；`rank among the world's top`（L2·PC）；`V-ing 状语`（L2·SB）→ 本句实例：…, forming a number of cultural enterprises, products and brands with international influence。"}, {"term": "", "zh": "", "cn": "数据显示，中国的出版物、影视作品、网络文学与动漫作品等在海外的销售量连年攀升。", "en": "Data show that the overseas sales of Chinese publications, film and television works, online literature and animation have been climbing year after year.", "ptype": "真题", "cat": "真题B", "map": "文化产品出海", "set": "CET6 2023·06·S2", "src": "CET6 2023·06·S2", "cls": "Chapter 11", "tip": "断句:分句①②;核心=②;①→来源/插入语(Data show that…);时锚:连年攀升→现在完成进行时;话题:补主语(→overseas sales of …);文化:出版物→publications；影视作品→film and television works；网络文学→online literature；动漫→animation", "ta": "插入语前置（Data show that…，连淑能 1993）；补主语；时态呼应（现在完成进行时）。", "te": "词性转换（\"销售量\"→sales）；惯用等值（\"连年攀升\"→climbing year after year）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`Data show that …`（L2·SB）→ 本句实例：Data show that … have been climbing year after year；`year after year`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国政府出台了一系列政策鼓励和支持更多具有中国元素的优秀文化产品走出国门，扩大海外市场份额，进一步提升中国文化的世界影响力。", "en": "The Chinese government has issued a series of policies to encourage and support more excellent cultural products with Chinese elements to go global, expand overseas market share and further enhance the global influence of Chinese culture.", "ptype": "真题", "cat": "真题B", "map": "文化产品出海", "set": "CET6 2023·06·S2", "src": "CET6 2023·06·S2", "cls": "Chapter 11", "tip": "断句:分句①②③④;核心=①;②③④→目的链(to V…);话题:补主语(→The Chinese government);文化:中国元素→Chinese elements；海外市场份额→overseas market share；世界影响力→global influence", "ta": "补主语；目的状语（to encourage and support…，连淑能 1993）；时态呼应（现在完成时）。", "te": "惯用等值（\"走出国门\"→go global）；动词并列（expand / enhance）；增补（further）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`a series of policies`（L2·PC）；`go global`（L2·PC）；`expand market share`（L2·PC）；`encourage sb to V`（L2·PC）。"}, {"term": "", "zh": "", "cn": "农业是中国的一个重要产业，从业者超过 3 亿。", "en": "Agriculture is an important industry in China, with more than 300 million workers.", "ptype": "真题", "cat": "真题B", "map": "农业粮食", "set": "CET6 2016·12·S3", "src": "CET6 2016·12·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→伴随介词短语(with more than 300 million workers);话题:补主语(→Agriculture);文化:农业→agriculture(教材术语库)", "ta": "补主语；伴随介词短语（with…，连淑能 1993）。", "te": "数字转换（\"3 亿\"→300 million）；增补（more than）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"农业\"教材定译 agriculture（教材术语库，S1）。", "rp": "`with more than … workers`（L2·PC）；`an important industry`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国农业产量全球第一，主要生产水稻、小麦和豆类。", "en": "China's agricultural output ranks first in the world, mainly producing rice, wheat and beans.", "ptype": "真题", "cat": "真题B", "map": "农业粮食", "set": "CET6 2016·12·S3", "src": "CET6 2016·12·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=①;②→分词状语(mainly producing…);话题:补主语(→China's agricultural output);文化:水稻→rice；小麦→wheat；豆类→beans/legumes", "ta": "补主语；分词状语（mainly producing…，连淑能 1993）。", "te": "增补（mainly）；惯用等值（\"全球第一\"→ranks first in the world）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`rank first in the world`（L2·PC）；`produce rice, wheat and beans`（L2·PC）。"}, {"term": "", "zh": "", "cn": "虽然中国的农业用地仅占世界的百分之十，但为世界百分之二十的人口提供了粮食。", "en": "Although China's farmland accounts for only 10 percent of the world's total, it feeds 20 percent of the world's population.", "ptype": "真题", "cat": "真题B", "map": "农业粮食", "set": "CET6 2016·12·S3", "src": "CET6 2016·12·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=②;①→让步状语从句(Although…);逻辑:让步→Although|While;话题:补主语(→China / its farmland);文化:农业用地→farmland/agricultural land；粮食→food", "ta": "让步状语从句前置（Although…，连淑能 1993）；补主语；意合→形合（让步显性化）。", "te": "惯用等值（\"占…\"→accounts for；\"为…提供粮食\"→feeds）；数字转换（\"百分之十\"→10 percent）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`account for … percent`（L2·PC）；`feed the population`（L2·PC）；`Although …, 主句`（L2·SB）→ 本句实例：Although China's farmland accounts for only 10 percent …, it feeds 20 percent of the world's population。"}, {"term": "", "zh": "", "cn": "中国 7700 年前开始种植水稻。", "en": "China began to grow rice 7,700 years ago.", "ptype": "真题", "cat": "真题B", "map": "农业粮食", "set": "CET6 2016·12·S3", "src": "CET6 2016·12·S3", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;时锚:7700年前(过去)→一般过去时;话题:补主语(→China);文化:水稻→rice", "ta": "补主语；时态呼应（一般过去时）。", "te": "数字转换（\"7700 年前\"→7,700 years ago）；词性转换（\"种植\"→grow）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`begin to grow`（L2·PC）；`… years ago`（L2·PC）。"}, {"term": "", "zh": "", "cn": "早在使用机械和化肥之前，勤劳和富有创造性的中国农民就已经采用各种各样的方法来增加农作物产量。", "en": "Long before the use of machinery and chemical fertilizers, hardworking and creative Chinese farmers had already adopted various methods to increase crop yields.", "ptype": "真题", "cat": "真题B", "map": "农业粮食", "set": "CET6 2016·12·S3", "src": "CET6 2016·12·S3", "cls": "Chapter 11", "tip": "断句:分句①②;核心=②;①→时间状语从句(Long before…);时锚:早在…之前/已经→过去完成时;话题:补主语(→hardworking and creative Chinese farmers);文化:化肥→chemical fertilizers；农作物产量→crop yields", "ta": "时间状语从句前置（Long before…，连淑能 1993）；补主语；时态呼应（过去完成时）。", "te": "增补（already / various）；词性转换（\"产量\"→yields）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`Long before …, S + had + V-ed`（L2·SB）→ 本句实例：Long before the use of machinery and chemical fertilizers, … had already adopted various methods …；`crop yields`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国农业最新的发展是推进有机农业。", "en": "The latest development of China's agriculture is the promotion of organic farming.", "ptype": "真题", "cat": "真题B", "map": "农业粮食", "set": "CET6 2016·12·S3", "src": "CET6 2016·12·S3", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;话题:补主语(→The latest development of China's agriculture);文化:有机农业→organic farming(教材术语库 农林复合经营 organic farming and agroforestry)", "ta": "补主语；名词化（\"推进\"→the promotion of）。", "te": "名词化（\"推进\"→the promotion of）；增补（the）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"有机农业\"教材相关定译 organic farming（教材术语库，S1）。", "rp": "`the promotion of`（L2·PC）；`organic farming`（L2·PC）。"}, {"term": "", "zh": "", "cn": "有机农业可以同时服务于多种目的，包括食品安全、大众健康和可持续发展。", "en": "Organic farming can serve multiple purposes at the same time, including food safety, public health and sustainable development.", "ptype": "真题", "cat": "真题B", "map": "农业粮食", "set": "CET6 2016·12·S3", "src": "CET6 2016·12·S3", "cls": "Chapter 11", "tip": "断句:单分句;核心=①;②→列举(including…);话题:补主语(→Organic farming);文化:食品安全→food safety；大众健康→public health；可持续发展→S1 sustainable development(库/教材)", "ta": "补主语；列举（including…）。", "te": "词性转换（\"服务于…目的\"→serve … purposes）；增补（multiple）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"可持续发展\"官方定译 sustainable development（gov/新华社关键词，S1，库内已收敛）。", "rp": "`serve purposes`（L2·PC）；`including A, B and C`（L2·PC）。"}], "exercises": [], "vocabHF": []}